programs.sol:
"""A contrastive-addition detector, with small lexical side responses.

The main negative response is on 'also' in 'but ... also', diminishing
with intervening words.  There are weaker responses to holistic modifiers,
UTF-8 continuations (especially square roots), and declaration modifiers.
Document starts use coarse form rules, with negative declaration openers;
the reasoning-section opener and repeated middle dots have negative responses.
These are a few observed patterns, not a complete account of lexical variation.
"""
import re

READS = ()
CONTRAST = re.compile(
    r'\b(but|however|although|though|while|yet)\b', re.I
)
ACCESS = re.compile(r'\b(public|protected|private|internal)\s*$')
DECLARATION_OPENERS = {'class', 'const', 'def', 'import', 'using', 'function'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    initial = carry is None or carry[0] != doc
    tail = '' if initial else carry[1]
    text = prefix.token_strings[-1]
    raw = prefix.token_bytes[-1]
    word = text.strip()
    value = 0.002

    if text == '<think>':
        value = -0.18
    elif word == 'also':
        value = -0.09
        matches = list(CONTRAST.finditer(tail))
        if matches:
            match = matches[-1]
            bridge = tail[match.end():]
            gap = len(re.findall(r'\w+', bridge))
            if gap <= 5 and not any(c in bridge for c in '.!?;'):
                strength, decay = (1.6, 0.52)
                if match[0][0].isupper():
                    strength, decay = (1.1, 0.65)
                if match[0].lower() not in {'but', 'however'}:
                    strength = 0.4
                value -= strength * decay ** gap
    elif word.lower() == 'also':
        value = -0.035
    elif word.lower() == 'overall':
        value = -0.28
    elif word == 'entire':
        value = -0.15
    elif word == 'override' and text.startswith(' '):
        value = 1.55 if ACCESS.search(tail) else 0.2
    elif word == 'abstract':
        value = 0.75 if ACCESS.search(tail) else -0.04
    elif word == 'class' and tail.rstrip().endswith('partial'):
        value = 0.7
    elif text and set(text) == {'·'} and len(text) > 1:
        value = -0.46
    elif raw and 0x80 <= raw[0] < 0xc0:
        value = -0.035
        # Complete a character split across the tokenizer's byte boundary.
        recent = b''.join(prefix.token_bytes[-2:]).decode('utf-8', 'replace')
        if recent.endswith('√'):
            value = -0.5 if recent.rstrip().endswith('(√') else -0.24

    if initial:
        if text == '<think>':
            value = -0.18
        elif text == '<|endoftext|>':
            value = 2.15
        elif text in DECLARATION_OPENERS:
            value = -0.6
        elif word.isalpha():
            value = 0.21
            if word.isupper():
                value = 0.16
            elif word.istitle():
                value = 0.12
        elif word.isdecimal():
            value = -0.08
        elif text.isspace():
            value = 0.45 if '\n' in text or '\t' in text else 0.0
        elif word in {',', ';'} or (text.startswith('.') and '\n' in text):
            value = 0.78
        else:
            value = 0.15

    return (doc, (tail + text)[-256:]), float(value)

"""A sparse spelling-fragment predictor, not a vocabulary lookup.

Tag/stag fragments are negative; rag/raj and lag fragments are positive.
Short ag/aj and g/j continuations depend on the unfinished word's last
consonant. Vowel-only tokens preserve it; other word boundaries clear it.
Romanization makes some of these rules apply across scripts. Japanese ji
has a stronger t-versus-r contrast. 'Stage' weakens in phase/count contexts.
Small start-of-document and formatting responses are included separately.
"""
import re
import string
from functools import lru_cache
from anyascii import anyascii
import inflect

READS = ()
_engine = inflect.engine()
COUNTS = {_engine.number_to_words(n) for n in range(1, 13)}
ORDINALS = {
    _engine.number_to_words(_engine.ordinal(n)) for n in range(1, 13)
}
PHASE_WORDS = COUNTS | ORDINALS | {
    'this', 'that', 'each', 'any', 'all', 'different', 'various',
    'early', 'earlier', 'late', 'later', 'initial', 'final', 'advanced',
}


# Signed strengths by the preceding consonant.
AG_WITH_ENDING = {
    't': -1.8,
    'd': -0.9,
    'r': 2.5,
    'l': 1.1,
}
BARE_AG_OR_AJ = {
    't': -3.0,
    'd': -1.7,
    'r': 5.7,
    'l': 1.65,
}
SINGLE_G_OR_J = {
    't': -0.8,
    'd': -0.55,
    'r': 0.85,
    'l': 0.45,
}
JAPANESE_JI = {
    't': -5.9,
    'r': 1.1,
}


@lru_cache(maxsize=32768)
def spelling(text):
    roman = anyascii(text)
    lower = roman.lower()
    root = lower.lstrip(string.punctuation + ' ')
    consonant = re.search(r'([bcdfghjklmnpqrstvwxz])[aeiouy]*$', lower)
    return roman, lower, root, consonant[1] if consonant else ''


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', 0)
    _, previous, consonant, age = carry
    text = prefix.token_strings[-1]
    roman, lower, root, last_consonant = spelling(text)
    value = 0.0
    if age == 0:
        value = -0.24 - 0.25 * roman.lstrip()[:1].isalpha()

    if re.fullmatch(r'stag(?:e[ds]?|ing)?', root):
        value -= 4.6
        value += 1.5 * root.endswith('s')
        value -= 2.0 * roman.lstrip(string.punctuation + ' ')[:1].isupper()
        value -= 0.8 * (not roman[:1].isspace())
        value += 2.5 * (previous.strip() in PHASE_WORDS)
        value -= 2.7 * (previous.strip() == 'on')
    elif root.startswith('tag') and len(root) <= 5:
        value -= 0.65 + 0.65 * (not roman[:1].isspace())
        value -= 3.0 * (roman.startswith(' T') and root.endswith('s'))
    elif re.fullmatch(r'[dft]?ra[gj](?:e[ns]?|s|ic)?', root):
        value += 3.6 - 2.0 * (root[0] != 'r')
    elif re.fullmatch(r'lag(?:e[nr]?|s)?', root):
        value += 1.4
    elif re.fullmatch(r'(?:on|back|off)stage', root):
        value -= 4.3

    if age and not lower[:1].isspace():
        previous_roman = spelling(prefix.token_strings[-2])[0]
        same_word_case = not roman[:1].isupper() or previous_roman.isupper()
        if same_word_case:
            weights = {}
            if (re.match(r'a[gj]', lower) and len(lower) <= 5
                    and previous[-1:] not in 'eiouy'):
                weights = AG_WITH_ENDING
                if lower in {'ag', 'aj'}:
                    weights = BARE_AG_OR_AJ
                if lower.startswith('ag') and previous.endswith('st'):
                    value -= 4.9
            elif lower in {'g', 'j'}:
                weights = SINGLE_G_OR_J
            elif text.lstrip('ー') == 'ジ':
                weights = JAPANESE_JI
            value += weights.get(consonant, 0.0)
    if '舞台' in text:
        value -= 6.0
    if text and len(text) > 1 and set(text) == {'·'}:
        value = -3.55
    if age == 1 and previous.strip() == 'title' and text == ':':
        value = 7.8
    if not last_consonant and re.fullmatch(r'[aeiouy]+', lower):
        last_consonant = consonant
    return (doc, lower, last_consonant, age + 1), float(value)

programs.haiku:
"""Layer-1 MLP down-projection feature 4225: a spelling detector.

It reads the word being spelled, letter by letter (the carry keeps the word so far), and
fires on a few word shapes. Values are typical activations for each shape:
  * strongly negative (about -4.5) on "stage" and its close forms: stage, staged, staging,
    unstage, backstage, Stage, katakana ステージ and 舞台 (theatre stage);
  * a colon right after a "Stage" heading is more negative still (about -7);
  * weakly negative (about -1.5) on plural or other stage-like words: stages, postage, hostages;
  * mildly negative (about -1.4) on "tag"/"tags" and German day names (Montag, Samstag);
  * positive (about +4) on rag/raj/rage-shaped words: rag, rage, raj, Anurag, Halorag, Betrag
    (not storage, average, flag);
  * weakly positive (about +1) on lag, drag, frag, slag;
  * a colon right after "Title" is mildly positive (about +1.5).
Everything else is 0.
"""
import re

READS = ()

STAGE = re.compile(r"stag(e|ed|ing)?$|舞台|ステージ$")
STAGE_OTHER = re.compile(r"(stages|stag|postage|hostages?)$")
TAG = re.compile(r"tags?$")
RAG_STRONG = re.compile(r"(?<![df])rag$|raj$|(?:^|out)rage$")
RAG_WEAK = re.compile(r"(lag|drag|frag|slag)$")


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[2] != doc:
        word, last = "", ""
    else:
        word, last = carry[0], carry[1]
    for ch in token:
        if ch.isalpha():
            word += ch.lower()
        elif word:
            last, word = word, ""
    if token == ":" and last == "stage":
        value = -7.0
    elif token == ":" and last == "title":
        value = 1.5
    elif STAGE.search(word):
        value = -4.5
    elif STAGE_OTHER.search(word):
        value = -1.5
    elif TAG.search(word):
        value = -1.4
    elif RAG_STRONG.search(word):
        value = 4.0
    elif RAG_WEAK.search(word):
        value = 1.0
    else:
        value = 0.0
    return (word, last, doc), value

programs.sol:
"""A local grammar response to 'the', plus an opening 'Title:' field.

Sentence-initial 'The' is strongly negative. Lowercase 'the' depends on
its introducer: genitive 'of', subordinate clauses and commas are negative;
location/path prepositions and copulas are weaker or positive. Capitalized
'The' at a document's beginning instead has a positive response. An opening
metadata 'Title:' has a rare, much larger positive separator response.
This ignores the small, varied responses to most other tokens.
"""
import re

READS = ()


def article(token, text):
    word = token.strip()
    if not text:
        if word == 'The':
            return 0.83 if token.startswith(' ') else 0.58
        return 0.16 if token.startswith(' ') else 0.08
    if word == 'The':
        if not token.startswith(' '):
            return -0.39 if text.endswith('\n') else 0.0
        if re.search(r'\.\s*$', text):
            return -0.63
        if re.search(r'[?!]\s*$', text):
            return -0.29
        if re.search(r':\s*$', text):
            return -0.20
        if re.search(r'[,;]\s*$', text):
            return 0.06
        if re.search(r'\w\s*$', text):
            return 0.05
        return -0.23
    if word == 'the' and not token.startswith(' '):
        return 0.28
    previous = re.findall(r'[A-Za-z]+|[^\w\s]', text)
    prev = previous[-1].lower() if previous else ''
    if prev == 'of':
        return -0.28
    if prev in {'about', 'between'}:
        return -0.29
    if prev in {'that', 'which', 'whether', 'where', 'how', 'because'}:
        return -0.34
    if prev in {'if', 'while', 'since', 'but'}:
        return -0.23
    if prev == ',':
        return -0.30 if word == 'the' else 0.12
    if prev in {'and', 'then', 'so', 'when', 'than'}:
        return -0.13
    if prev in {'in', 'within', 'during', 'by'}:
        return -0.07
    if prev in {'at', 'over', 'through', 'across', 'around', 'outside'}:
        return 0.17
    if prev in {'to', 'into', 'after', 'before', 'under', 'with', 'or'}:
        return 0.08
    if prev in {'is', 'are', 'was', 'were', 'be', 'been'}:
        return 0.07
    if prev in {'have', 'has', 'all'}:
        return 0.16
    if prev in {'(', '"', "'", '“'}:
        return 0.23
    return 0.02 if word == 'the' else 0.18


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    value = 0.0
    if token.strip().lower() == 'the':
        value = article(token, text)
    elif token == ':' and text == 'Title':
        value = 23.32
    elif not text and token == 'Title':
        value = -0.47
    return (doc, (text + token)[-160:]), value

"""Approximate an im/ym spelling response and a few temporal phrases.

Short im/ym pieces inside words give negative values. Transliteration extends
this to Latin, Cyrillic and Greek; an i/y ending followed by m across a token
boundary also counts, including selected single-kana joins. Long pieces and word starts are weaker. A short continuation can
retain some negative response. Separately, time/moment after this or that are
positive, as are imaginary and full-time. Only the previous token is retained.
"""
import re
from functools import lru_cache
import regex
from anyascii import anyascii

READS = ()
ALPHABET = regex.compile(r'[\p{Latin}\p{Cyrillic}\p{Greek}]+')
KANA = regex.compile(r'[\p{Hiragana}\p{Katakana}]')
CYRILLIC = regex.compile(r'\p{Cyrillic}')


@lru_cache(maxsize=65536)
def spelling(text):
    roman = anyascii(text).lower()
    tail = re.search(r'[a-z]+$', roman)
    return (roman, roman.strip(), bool(ALPHABET.fullmatch(text.strip())),
            bool(CYRILLIC.search(text)), bool(KANA.fullmatch(text)),
            tail.group() if tail else '')


def response(text, previous_text):
    roman, s, alphabetic, cyrillic, kana, _ = spelling(text)
    _, preceding, prev_alpha, _, prev_kana, previous = spelling(previous_text)
    initial = bool(roman and roman[0].isspace()) or not previous

    if s in ('time', '-time', '_time', '.time'):
        if preceding in ('this', 'that'):
            return 3.0
        if preceding in ('my', 'your', 'his', 'her', 'our', 'their'):
            return 1.1
        if preceding == 'full':
            return 2.4
        if preceding in ('half', 'part'):
            return 0.8
        if preceding in ('all', 'space'):
            return -0.5
        if preceding in ('the', 'same', 'in', 'of'):
            return 0.4
        if preceding in ('at', 'to', 'over', 'long', 'every', 'each'):
            return -0.1
        return 0.6 if text.strip() == 'Time' else 0.2
    if s == 'moment':
        return 3.1 if preceding in ('this', 'that') else 0.15
    if s == 'imaginary':
        return 1.8

    value = 0.0
    match = re.search(r'[iy]m', s) if alphabetic and len(s) <= 8 else None
    if match:
        short = len(s) <= 3
        value = -0.7 - 0.65 * short
        if initial:
            value += 0.3 + 0.95 * short
        before = s[match.start() - 1] if match.start() else previous[-1:]
        if not initial or match.start():
            if before in ('a', 'e', 'i', 'o', 'u'):
                value += 0.2
            elif before in ('r', 'l'):
                value -= 0.2
        if short and s[match.end():match.end() + 1] in ('a', 'o', 'u'):
            value -= 1.5
        if len(s) > 4:
            value += 0.3
        if cyrillic and len(s) > 2:
            value += 0.45
        if re.search(r'sym|gym|stim|prim', previous + s):
            value += 0.2
        if 'ı' in text:
            value -= 1.05
        if (previous + s).endswith('facsim'):
            value = -7.0

    if not initial and previous[-1:] in ('i', 'y') and s.startswith('m'):
        if alphabetic and prev_alpha and not text[:1].isupper():
            value -= 1.85 if len(s) <= 3 else 0.4
        elif kana and prev_kana and text != 'も':
            value -= 3.0
    if not initial and alphabetic and len(s) <= 3:
        if re.search(r'[iy]m', preceding):
            value -= 0.45
    return value


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == document else ''
    text = prefix.token_strings[-1]
    return (document, text), float(response(text, previous))

"""Approximate a multilingual 'il'/'yl' subword signal.

Short il-initial pieces and immediate continuations get a weak response;
completing i+l across adjacent tokens gets the strongest response.
Transliteration merges y/i and Katakana r/l spellings. Han, Hangul and
Hiragana are ignored. A separate rule handles an initial Title: label.
These spelling rules leave word-specific exceptions unmodeled.
"""
from anyascii import anyascii
from functools import lru_cache
import re
import regex

READS = ()


@lru_cache(maxsize=50000)
def spelling(text):
    text = regex.sub(
        r'[\p{Script=Han}\p{Script=Hangul}\p{Script=Hiragana}]', ' ', text)
    text = regex.sub(r'\p{Script=Katakana}+',
                     lambda m: anyascii(m.group()).replace('r', 'l'), text)
    # Use the classical e-spelling of Greek eta, not modern i.
    text = text.translate(str.maketrans('ηήΗΉ', 'eeEE'))
    return re.sub(r'(?<![aeou])y', 'i', anyascii(text).lower())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        previous, tail, title = '', '', False
    else:
        _, previous, tail, title = carry
    s, p = spelling(text), spelling(previous)
    continuing = bool(s and s[0].isalpha() and p and p[-1].isalpha())
    value = 0.0
    if 'il' in s:
        value = 0.4 if len(s.strip()) <= 3 else 0.1
        if s.startswith('il'):
            value = 1.3 if len(s) <= 4 else 0.7
    if continuing:
        if p.endswith('i') and s.startswith('l') and not text[0].isupper():
            value = 3.3 if len(p.strip()) <= 2 else 2.0
        elif tail.endswith('il'):
            if len(p.strip()) <= 2:
                value = max(value, 2.1 if len(s) <= 2 else 1.2)
            elif len(s) <= 3:
                value = max(value, 1.4 if s[0] in 'aeiou' else 0.55)
            else:
                value = max(value, 0.4)
        elif 'il' in tail[-4:]:
            value = max(value, 0.35)
    if title and text == ':':
        value = 7.35
    new_title = text == 'Title' and previous in ('', '<|endoftext|>')
    word = re.search(r'[a-z]+\Z', tail + s)
    tail = word.group()[-12:] if word else ''
    return (doc, text, tail, new_title), value

"""Approximate the component using unfinished UTF-8 characters.

Predictions depend on the possible character's script. Accented Greek and
Runic byte fragments are especially strong; kana prefixes are quiet. A
complete token is usually quiet, except for repeated middle dots (negative)
and a file-opening line-comment header (positive). Ordinary starts are negative.
"""
import codecs
from functools import lru_cache
import regex

READS = ()


@lru_cache(maxsize=4096)
def character_kind(pending):
    """Classify the interval of characters compatible with these UTF-8 bytes."""
    width = 2 if pending[0] < 224 else 3 if pending[0] < 240 else 4
    number = pending[0] & ((1 << (7 - width)) - 1)
    for byte in pending[1:]:
        number = (number << 6) | (byte & 63)
    shift = 6 * (width - len(pending))
    low = number << shift
    high = min(low + (1 << shift) - 1, 0x10ffff)
    endpoints = chr(low) + chr(high)
    for kind, pattern in (
        ('accented Greek', r'\p{Block=Greek_Extended}'),
        ('Runic', r'\p{Script=Runic}'),
        ('Han', r'\p{Script=Han}'),
        ('Hangul', r'\p{Script=Hangul}'),
        ('combining', r'\p{Block=Combining_Diacritical_Marks}'),
        ('kana', r'[\p{Script=Hiragana}\p{Script=Katakana}]'),
    ):
        if regex.search(pattern, endpoints):
            return kind, width - len(pending)
    return 'other', width - len(pending)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    previous = b'' if start else carry[1]
    start = start or carry[2]
    token = prefix.token_bytes[-1]
    decoder = codecs.getincrementaldecoder('utf8')('replace')
    decoder.decode(previous + token)
    pending = decoder.getstate()[0]
    value = -0.18 if start else 0.0
    if pending:
        kind, needed = character_kind(pending)
        separate_byte = len(token) == 1 and 128 <= token[0] < 192
        bare_prefix = token.strip() == pending
        if needed == 1:
            value = 0.63 if separate_byte else 0.15 if bare_prefix else 0.12
            if kind == 'accented Greek':
                value = 1.12 if separate_byte else 0.5
            elif kind == 'Runic':
                value = 1.25 if separate_byte else 0.42
            elif kind == 'Han':
                value = 0.70 if separate_byte else 0.32
            elif kind == 'Hangul':
                value = 0.74 if separate_byte else 0.47
            elif kind == 'combining':
                value = 0.71
            elif kind == 'kana':
                value = 0.0
        elif needed == 2 and kind == 'Hangul':
            value = 0.24
        else:
            value = 0.0
    text = token.decode('utf8', 'replace')
    if len(text) >= 2 and set(text) == {'·'}:
        value = -1.71
    if start and token == b'//\n':
        value = 2.53
    return (doc, pending, text == '<|endoftext|>'), value

"""Approximate local boundary effects with character and token shapes.

The strongest positive case is a closing curly quote enclosing one East Asian
character.
Spaces, list commas, and brackets after short East Asian spans get smaller
positive values. Byte fragments are joined before counting characters.
Markdown headings after unfinished prose get a negative value. Remaining
cases use coarse token shapes and document starts; lexical variation is lost.
"""
from functools import lru_cache
import regex

READS = ()
HAN = regex.compile(r'\p{Script=Han}+')
EAST_ASIAN_TAIL = regex.compile(
    r'[\p{Script=Han}\p{Script=Hangul}'
    r'\p{Script=Hiragana}\p{Script=Katakana}]+$'
)
OPENERS = {'”': '“', '」': '「', '』': '『', '）': '（',
           ')': '(', ']': '[', '】': '【', '"': '"'}


@lru_cache(maxsize=65536)
def is_han(text):
    return bool(HAN.fullmatch(text))


def response(text, tail, start):
    if text and set(text) == {'·'} and len(text) >= 2:
        return -1.15  # Repeated typographic middle dots.
    if start:
        if text in ('int', 'string'):
            return -2.3  # Document-initial programming type keywords.
        if text.isdecimal():
            return -0.20
        if text.isspace():
            return -0.15
        if text.isascii() and text.lstrip().isalpha():
            return -0.05 if text[0].isspace() else -0.18
        return -0.04

    match = EAST_ASIAN_TAIL.search(tail)
    n = len(match[0]) if match else 0
    opener = OPENERS.get(text.strip())
    if opener and n and tail[:-n].endswith(opener):
        if text.strip() == '”':
            if n == 1:
                return 2.53
            if n == 2:
                return 0.13
        return 0.38 if n == 1 else 0.08 if n == 2 else -0.02
    if text == '、':
        return 0.24 if n == 1 else 0.02
    if text == '：' and n == 1:
        return 0.28
    if text in (' ', '\u200b', ' \u200b') and n:
        return 0.71 if n == 1 else 0.03
    if '\ufffd' in text:
        if text.startswith(' '):
            return 0.76 if n == 1 else -0.035
        return 0.02

    if text == '###' and tail.endswith('\n\n'):
        paragraph = tail.rstrip().rsplit('\n\n', 1)[-1]
        if paragraph == 'More information':
            return -0.40
        if ('\n' not in paragraph and len(paragraph.split()) >= 10
                and paragraph[-1:] not in '.!?。！？'):
            return -0.30
    if is_han(text):
        if len(text) == 1:
            return -0.02 if n == 1 else 0.02
        return 0.04 if n == 1 else -0.01
    return -0.001


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    old = b'' if start else carry[1]
    tail = old.decode('utf-8', errors='ignore')
    value = response(prefix.token_strings[-1], tail, start)
    new = (old + prefix.token_bytes[-1])[-192:]
    return (doc, new), value

"""A current-word detector for 'on' and several translations.

Common bound expressions ('based/depend/focus on', effects on, 'so on')
are much weaker than ordinary 'on'. Word boundaries separate 'on' from
word endings. Secondary responses mark long underscore blanks, Chinese
where/which questions, and commas before closing quotation marks.
"""
import re
import wordnet

READS = ()

# Multilingual 'on': Slavic na, German auf, French sur, Scandinavian på,
# Dutch op, and Arabic على. These are lexical cues, not language detection.
ON_TRANSLATIONS = {
    'na': 0.87, 'Na': 0.4, 'на': 0.65, 'На': 1.0,
    'auf': 0.77, 'Auf': 0.7, 'sur': 1.07, 'på': 1.6,
    'På': 1.6, 'op': 0.6, 'على': 1.05,
