ATTENTION_OR_DEPENDENCE = {'depend', 'dependent', 'focus', 'concentrate'}
CAUSAL_RELATION = {'effect', 'impact', 'influence', 'emphasis',
                   'dependence', 'rely'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lstrip('-_').lower()
    boundary = (not history or not history[-1].isalpha()
                or token[:1].isspace() or token[:1] in '-_')
    value = 0.0
    if lower == 'on' and (boundary or word == 'On'):
        value = 1.4 if word not in ('On', 'ON') else 1.0
        previous = re.search(r'([A-Za-z]+)[^A-Za-z]*$', history)
        previous = previous[1].lower() if previous else ''
        forms = set(wordnet.base_forms(previous)) | {previous}
        if not history:
            value = 0.1 if word == 'On' else 0.5
        elif previous == 'so':
            value = -0.3
        elif forms & ATTENTION_OR_DEPENDENCE:
            value = 0.13
        elif 'base' in forms:
            value = 0.21
        elif forms & CAUSAL_RELATION:
            value = 0.4
    elif lower == 'upon' and boundary:
        value = 1.5
    elif lower == 'onto' and boundary:
        value = 0.48
    elif boundary:
        value = ON_TRANSLATIONS.get(word, 0.0)
    if word in ('哪里', '哪裡', '哪种', '哪種'):
        value = 0.7
    elif word in (',"', ',”'):
        value = 0.4
    elif len(word) >= 4 and not word.strip('_'):
        value = 1.2 if token.startswith(' ') else 0.6
    return (doc, (history + token)[-100:]), value

"""Whitespace separators, damped in documents with frequent line breaks.

For a space/tab token, use its width, whether the previous token was blank
or ended a line, and the earlier frequency of blank and line-break tokens.
Four- and eight-space blocks have stronger, separately calibrated responses.
Other line-start blocks get a bonus when earlier standalone whitespace is
scarce. The response fades with document position. Document-initial tokens have
separate digit/case/control-token baselines. Small corrections cover periods
after initials, interpuncts and backticks. This is a partial approximation;
it deliberately does not memorize words or token identities.
"""
from math import log1p

READS = ()


def whitespace_value(s, previous, position, blanks, breaks):
    after_line = float(previous.endswith('\n'))
    after_blank = float(previous.isspace())
    blank_rate = blanks / position
    break_rate = breaks / position
    age = log1p(position)
    early = 1 / (position + 1)
    spaces, tabs = s.count(' '), s.count('\t')
    if tabs == 0 and spaces == 4:
        value = (0.065 + 0.055 * after_line + 0.168 * after_blank
                 - 0.115 * blank_rate - 1.325 * break_rate
                 - 0.008 * age + 2.487 * early)
    elif tabs == 0 and spaces == 8:
        value = (0.180 + 0.133 * after_line + 0.276 * after_blank
                 + 0.034 * blank_rate - 0.800 * break_rate
                 - 0.033 * age + 0.450 * early)
    else:
        value = (0.041 + 0.064 * after_line + 0.029 * after_blank
                 - 0.104 * break_rate - 0.0113 * age + 0.292 * early
                 + 0.0063 * log1p(spaces + 4 * tabs))
        if tabs == 0 and spaces == 2:
            value -= 0.088
        if tabs == 0 and spaces >= 3 and after_line:
            # A new whitespace boundary is stronger than familiar indentation.
            value += 0.317 * max(0.0, 1.0 - 200 * blank_rate)
    return max(-0.4, min(1.0, value))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, previous, blanks, breaks = 0, '', 0, 0
    else:
        _, position, previous, blanks, breaks = carry
        position += 1

    word, initial = s.strip(), previous.strip()
    value = -0.001
    if position == 0:
        if s.startswith('<|'):
            value = 0.186
        elif word.isdigit():
            value = -0.497
        elif len(word) == 1 and word.isascii() and word.isupper():
            value = -0.277
        elif word[:1].isupper():
            value = -0.093
        else:
            value = -0.17
    elif s and not s.strip(' \t'):
        value = whitespace_value(s, previous, position, blanks, breaks)
    elif s == '.' and len(initial) == 1:
        if initial.isascii() and initial.isupper():
            value = 0.087 if len(previous) == 1 else 0.217
    elif s == '·':
        value = 0.206
    elif '`' in s:
        value = -0.02 if s.count('`') == 1 else -0.04

    carry = (doc, position, s,
             blanks + int(s.isspace()), breaks + int('\n' in s))
    return carry, value

