import unicodedata
from functools import lru_cache
import wordnet
import inflect

READS = ()
NOUN_INFLECTIONS = inflect.engine()
PERSONAL = set('i me you he him she her we us they them myself yourself '
               'himself herself ourselves yourselves themselves'.split())
POSSESSIVE = {'my', 'your', 'his', 'her', 'our', 'their'}
REFLEXIVE = set('myself yourself himself herself ourselves yourselves '
                'themselves'.split())
ROLE_CONTEXT = set('role job purpose relationship capacity career work working '
                   'worked responsibility responsibilities experience'.split())


@lru_cache(maxsize=1024)
def plural_person(word):
    """Plural human nouns, using WordNet rather than a list of professions."""
    if not word.isalpha():
        return False
    singular = NOUN_INFLECTIONS.singular_noun(word)
    return bool(singular and wordnet.is_a(singular, 'person'))


def phrase_value(history, token):
    # Lowercase i and capital US usually denote a variable or the country.
    words = [
        t.strip().lower() if t.strip() not in {'i', 'US'} else ''
        for t in history
    ]
    word = token.strip().lower()
    previous = words[-1] if words else ''
    before = words[-2] if len(words) > 1 else ''
    if len(word) == len(previous) == 1:
        if (unicodedata.decimal(word, -1) == 0
                and unicodedata.decimal(previous, -1) == 6):
            return 1.54
    if previous == 'our' and word in {'lady', 'lord'}:
        return 5.4
    if word.startswith(('作为', '身为')):  # Chinese 'in the role of'.
        initial = not previous or not any(c.isalnum() for c in previous)
        if previous in {'我们', '你们', '我', '你'}:
            return -6.0
        return -4.4 if initial or word.startswith('身为') else -0.5
    if word in {'als', 'como'}:  # German / Portuguese 'as'.
        return -0.25 if word == 'als' else -0.52
    if previous in PERSONAL:
        if word in {'and', 'or'}:
            strong = previous in {'i', 'you', 'he', 'she', 'we'}
            if word == 'or':
                return -3.8 if strong else -1.3
            if previous in {'he', 'she', 'you'}:
                return -2.8
            return -2.0 if strong else -0.9
        if word == ',':
            if previous == 'we':
                return -5.5
            return -1.1 if previous in {'i', 'you', 'me', 'us'} else -0.3
        if word == 'as':
            if previous == 'we':
                return -10.0
            return -1.5 if previous != 'they' else 0.0
        if word in REFLEXIVE:
            return -2.9
        if previous in {'we', 'you'} and plural_person(word):
            return -5.8
        if previous == 'we' and word == 'all':
            return -1.7
        if previous == 'we' and word == 'the' and token[:1].isspace():
            return -5.0
    if previous == 'here' and word in {'in', 'at', 'on'}:
        return -3.2
    if previous in POSSESSIVE and token[:1].isspace():
        if word == 'fellow':
            return -2.0
        if word == 'job':
            return -3.3 if previous in {'my', 'your', 'our'} else -1.9
        if previous in {'my', 'your', 'our'}:
            if word == 'name' and previous == 'my':
                return -2.6
            if word == 'task':
                return -1.9
            if word == 'family':
                return -0.5 if previous == 'your' else -2.3
            if word in {'company', 'group'}:
                return -1.2
    if word == 'of':
        return {'rest': -3.1, 'field': -0.85, 'future': -2.3,
                'behalf': -1.4, 'role': -0.6}.get(previous, 0.0)
    if word in {'a', 'an', 'the'}:
        definite = word == 'the'
        if previous == 'as':
            scale = 0.4 if definite else (1.15 if word == 'an' else 1.0)
            if history[-1].strip() == 'As':
                strength = 3.1
            elif before in PERSONAL or before in ROLE_CONTEXT:
                strength = 1.6
            elif before in {'and', 'but'}:
                strength = 2.8
            elif len(words) > 1 and (
                    not before or not any(c.isalnum() for c in before)):
                strength = 1.2
            elif any(w in PERSONAL for w in words[-5:]):
                strength = 1.2
            else:
                strength = 0.35
            return -strength * scale
        if previous in {'are', 'am', "'re", '’re', "'m", '’m'}:
            if previous == 'are' and before in {'you', 'we'}:
                return -3.6 if before == 'you' else -3.0
            if previous in {"'re", '’re'}:
                return -2.1
            if previous in {"'m", '’m'}:
                return -0.55
            if previous == 'am' and before == 'i':
                return -0.85
            if before == 'they':
                return -0.5
            return -0.12
        if previous == 'being':
            return -0.56 if definite else -1.5
        if previous == 'be' and before == 'to':
            wishing = any(
                w in {'want', 'wanted', 'wish', 'hope', 'like'}
                for w in words[-4:]
            )
            if wishing:
                return -1.4 if definite else -3.2
            return -0.18 if definite else -0.6
        if previous in {'was', 'were'} and before in PERSONAL:
            return -0.6
    if word == 'as':
        if token.strip() == 'As':
            return -0.56
        if previous in ROLE_CONTEXT or previous in {'and', 'but'}:
            return -0.65
    if previous == '(' and word in {'and', 'or', 'as'}:
        return -0.92
    if word == ',' and previous in {'example', 'instance'}:
        return 0.45
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = () if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    return (doc, (history + (token,))[-5:]), phrase_value(history, token)

