"""Layer-1 MLP down-projection component 4234, as a short rule list.

The component writes to the residual stream in two opposite directions, and this program
predicts its activation from the last few tokens:

* Positive on the digit 0 right after the digit 6, as in "60", "600", "6 0" in code. It is
  about +2 when the 6 starts a number and about +1 when the 6 sits inside a longer digit
  string.
* Negative on the word after "as" or a sentence-initial "As" when it introduces a role or
  capacity: "As a", "As an", "work as a", "as an AI". The article right after "As" is the
  strongest (about -3.6), after a mid-sentence "as" weaker (about -0.8). Frames like
  "such as a", "used as a", "described as a" do not fire.
* Negative on a few fixed phrases: "here in/at/on" (-4.5), "rest of", "future of", "field
  of", "role of" (-2), "my/your family, wife, company, job" (-1.9), "being/be/are a" (-0.5),
  and the Chinese role words 作为 and 身为 (-2).
* Negative on a comma, "and" or "as" right after a personal pronoun ("you and", "me as"),
  about -1.1.

Everything else predicts 0. The fit is rough: this captures about a fifth of the variance,
and the rest is diffuse small activity over many tokens that no short rule describes.
"""
READS = ()

ARTICLES = {" a", " an"}
SUCH_AS = {" such", " used", " serve", " served", " serves", " described", " defined",
           " treated", " well", " seen", " this", " to", " expressed"}
BE_VERBS = {" are", " be", " being", " become", "'re", " am"}
PRONOUNS = {" you", " me", " I", " he", " she", " we", " them", " him", " her", " myself", "self", " us"}
POSSESSIVES = {" my", " your"}
ROLE_NOUNS = {" family", " wife", " company", " job"}
ROLE_OF_NOUNS = {" rest", " future", " field", " role"}
AS_WORDS = {"As", " As"}


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    cur = toks[-1]
    prev = toks[-2] if len(toks) > 1 else ""
    prev2 = toks[-3] if len(toks) > 2 else ""
    if "作为" in cur or "身为" in cur:
        return carry, -2.0
    if cur == "0" and prev == "6":
        return carry, 1.1 if prev2.strip().isdigit() else 2.1
    if prev in AS_WORDS and cur in ARTICLES:
        return carry, -3.6
    if prev in AS_WORDS and cur == " the":
        return carry, -1.4
    if cur in AS_WORDS:
        return carry, -0.6
    if prev == " as" and cur in ARTICLES and prev2 not in SUCH_AS:
        return carry, -0.8
    if prev == " here" and cur in (" in", " at", " on"):
        return carry, -4.5
    if prev in BE_VERBS and cur in ARTICLES:
        return carry, -0.5
    if prev in PRONOUNS and cur in (" and", ",", " as"):
        return carry, -1.1
    if prev in ROLE_OF_NOUNS and cur == " of":
        return carry, -2.0
    if prev in POSSESSIVES and cur in ROLE_NOUNS:
        return carry, -1.9
    return carry, 0.0

