# Initial consonants and vowel groups in syllable spellings, not whole words.
ONSET = {'ph': -1.6, 's': -.8, 'c': -.5, 'm': -.3, 'ng': -.3,
         'kh': 1.0, 't': .45, 'n': .45, 'g': .35, 'h': .35,
         'qu': .45, 'tr': .2, 'x': .2}
VOWEL = {'â': -.6, 'ươ': -1.0, 'ơ': -.4, 'âu': -1.0, 'ô': -.3,
         'ă': -.2, 'ôi': -.3, 'o': .4, 'ê': .2, 'ư': .5,
         'ưa': .35, 'iê': .35, 'êu': .3, 'ươi': .3, 'ơi': .2}
SYLLABLE = re.compile(
    r'(ngh|ng|nh|ph|th|tr|ch|kh|gh|gi|qu|[bcdđghklmnpqrstvx]?)'
    r'([aăâeêioôơuưy]+)(ng|nh|ch|[cmnpt]?)$')


@lru_cache(maxsize=8192)
def syllable(s):
    word = s.strip().lower()
    # Vietnamese tone letters and horn vowels provide language evidence.
    marked = any(0x1EA0 <= ord(c) <= 0x1EF9 or c in 'ơưƠƯ' for c in s)
    m = SYLLABLE.fullmatch(word)
    value = 0.0
    if m and (any(c in word for c in 'âêôăơư') or m[2] in ('o', 'oi')):
