    if regex.fullmatch(r'\p{Cyrillic}+', text) and s == 'in' and p.endswith('n'):
        return -9.0
    if (regex.search(r'\p{Cyrillic}|\p{Katakana}|\p{Arabic}', text)
            and re.search(r'n[iy]n(?:[aeiogs]|t)?$', p[-2:] + s)):
        return -4.0
    if not regex.fullmatch(r'\p{Latin}+', text):
        return 0.0
    if (p.endswith('n') and not history.endswith('\\n')
            and not (text[0].isupper() and not text.isupper())):
        if s == 'ine':
            return -8.4
        if s in {'ina', 'inas'}:
            return -7.0
        if s in {'int', 'inth'}:
            return -4.1
        if re.fullmatch(r'in(?:[aeio]s?|s|n|us|h|k)?', s):
            return -1.0 if previous.strip().lower() == 'non' else -7.2
        for pattern, value in N_ENDINGS:
            if re.fullmatch(pattern, s):
                return value
    if s in {'inine', 'anine'}:
        return -7.7
    if s in {'inin', 'nin'}:
        return -5.5
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history, previous = ('', '') if carry is None or carry[0] != doc else carry[1:]
    text = prefix.token_strings[-1]
    value = response(history, previous, text)
    return (doc, (history + text)[-80:], text), value

programs.haiku:
"""Layer 1, MLP down-projection, component 4237: a negative "I think" detector.

What it does. The component is silent almost everywhere. It goes strongly negative on
the verb "think" when it comes straight after a first-person "I" ("I think the answer
is ...", about -8.5), and somewhat less after a negation ("I don't think", about -5).
It is weaker on "believe" after "I" (about -4), on "guess"/"suppose" after "I" (about
-1), on "sure" after "not" ("not sure", about -2) and on "Union" (Fort Union, National
Union, trade union; about -3).

It also goes negative on chemical names that the tokenizer splits into pieces, when the
last piece is "-in" or "-ine" (melanin, methionine, arginine, quinine, creatinine,
glucoraphanin): about -8 there. Ordinary "in"/"ine" pieces of other words stay near zero,
so only pieces completing a word that contains one of a few chemical stems count.

The values are typical activations on training text, rounded. Everything else is 0.
"""

READS = ()

I_WORDS = {"I", "i"}
# "t" is the piece left when a tokenizer splits "don't" as "don" + "t".
NEGATIONS = {"not", "don't", "don’t", "n't", "’t", "'t", "t"}
GUESS_VERBS = {"guess", "suppose"}
PIECES = {"in", "ine", "inine", "nin", "inin", "ino", "ina", "anine"}
# stems of chemical names: amino acids, pigments, alkaloids, dyes, glycosides
CHEM_STEMS = ("argin", "methion", "melan", "quin", "creat", "cyan", "tropon",
              "apocyn", "raphan", "tann", "phenylalan", "lysin")


def word_so_far(prefix):
    """The current word up to the token before the newest one (no-space pieces joined)."""
    pieces = []
    i = len(prefix) - 2
    while i >= 0 and prefix.token_strings[i] and not prefix.token_strings[i].startswith(" "):
        if prefix.document_ids[i] != prefix.document_ids[-1]:
            break
        pieces.append(prefix.token_strings[i])
        i -= 1
    return "".join(reversed(pieces))


def step(carry, prefix, upstream):
    if len(prefix) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return carry, 0.0
    raw = prefix.token_strings[-1]
    cur = raw.strip()
    prev = prefix.token_strings[-2].strip().lstrip("\"“‘(")
    if cur == "think":
        if prev in I_WORDS:
            return carry, -8.5
        if prev in NEGATIONS:
            return carry, -5.0
    if cur == "believe" and prev in I_WORDS:
        return carry, -4.0
    if cur in GUESS_VERBS and prev in I_WORDS:
        return carry, -1.0
    if cur == "sure" and prev in NEGATIONS:
        return carry, -2.0
    if cur in ("Union", "union"):
        return carry, -3.0
    if raw in PIECES and not raw.startswith(" "):
        if any(stem in word_so_far(prefix) for stem in CHEM_STEMS):
            return carry, -8.0
    return carry, 0.0


def main():
    """Demo: the prediction for a short sentence, token by token."""
    tokens = ["I", " think", " so", ".", " I", " don", "'t", " think", " it", " works"]
    docs = [0] * len(tokens)
    for i in range(len(tokens)):
        pre = _Prefix(tokens[: i + 1], docs[: i + 1])
        _, value = step(None, pre, {})
        print(f"{tokens[i]!r:12} {value:+.1f}")


class _Prefix:
    """Minimal stand-in for the prefix object, for the demo in main()."""

    def __init__(self, token_strings, document_ids):
        self.token_strings = token_strings
        self.document_ids = document_ids

    def __len__(self):
        return len(self.token_strings)


if __name__ == "__main__":
    main()

"""v8: a definition-slot detector for one MLP neuron-direction of layer 1 (down_proj:4239).

What it responds to. This component is mostly silent. It goes strongly negative on the word
that opens a definition of a symbol or term: the "is/denotes/stands for/refers to" linking a
symbol to its meaning, and the "the" right after it, as in "where L is [the] length of ...",
"x_k represents [the] local coordinates", "Towing capacity refers [to] the ...". It is most
negative when the subject is a math symbol inside a "where ..." list. Pronoun subjects
("it is", "this is") give nothing. A run of middle dots gives a constant positive value.

How it is predicted: each rule below looks only at the one or two tokens before the current
token, plus whether "where" occurred in the last 12 tokens. Weights are least-squares fits to
the component's activation on 2048 training rows, rounded.
"""
import re

READS = ()

DEFINING_VERBS = {"denotes", "denote", "denoting", "means", "represents", "represent",
                  "representing", "refers", "refer", "stands", "stand", "indicates", "indicate",
                  "indicating", "describes", "returns", "contains", "containing", "表示"}
COPULAS = {"is", "are", "be", "was", "were"}
ARTICLES = {"the", "a", "an", "The", "A"}


def is_symbol(tok):
    """A math-like symbol: a letter or Greek letter with an optional subscript digit, a number,
    a LaTeX macro, or a dollar sign."""
    return bool(re.fullmatch(r"[A-Za-z]\d*|[α-ωΑ-Ω]|\d+|\$+|\}\$|\\\w+", tok))


def step(carry, prefix, upstream):
    toks = [x.strip() for x in prefix.token_strings]
    t = len(toks) - 1
    cur = toks[t]
    p1 = toks[t - 1] if t >= 1 else ""
    p2 = toks[t - 2] if t >= 2 else ""
    if cur == "··":  # a run of middle dots (leader dots): a constant, degenerate case
        return None, 2.65
    if t == 0 or prefix.document_ids[t] != prefix.document_ids[t - 1]:
        return None, 0.25  # first token of a document
    where = "where" in toks[max(0, t - 12):t]
    v = 0.0
    if cur in DEFINING_VERBS:
        v = -2.2 if is_symbol(p1) or is_symbol(p2) else -0.7
    elif cur in COPULAS:
        if is_symbol(p1):
            v = -3.9 if where else -0.5
        elif p1 in (")", '"', ""):
            v = -0.2
    elif cur in ARTICLES and (p1 in COPULAS or p1 in DEFINING_VERBS):
        if is_symbol(p2):
            v = -5.7 if where else -1.6
        elif p1 in DEFINING_VERBS:
            v = -0.9
        else:
            v = -0.3
    elif cur in ARTICLES and p1 == "=":
        v = -0.5
    elif cur in ("to", "for") and p1 in DEFINING_VERBS:
        v = -1.6
    elif cur in ("—", "–"):
        v = -0.5
    return None, v

programs.sol:
"""Sparse lexical-completion pulses, strongest on geographic compounds.

Large regions, oceans and hemispheres give negative pulses; directional local
names and movement suffixes give positive ones. Smaller rules cover selected
scientific, financial and sports collocations, US currency notation, and repeated
centered dots. These are conspicuous training patterns, not a complete account
of the component: most weak word-specific responses are left at zero.
The short byte buffer is reset at document boundaries.
"""
import re

READS = ()
WORD = re.compile(r"[a-z]+(?:-[a-z]+)*\Z", re.I)
TOWN = re.compile(r'\b(?:north|south|east|west)[ -]?'
                  r'(gate|shore|bridge|bound|port|wood|field|more|main|ward|end)\Z')
DIRECTIONS = {'north', 'south', 'east', 'west', 'northern', 'southern',
              'eastern', 'western', 'central', 'southeast', 'southwest',
              'northeast', 'northwest'}
SEAS = {'red', 'baltic', 'black', 'north', 'mediterranean', 'caribbean',
        'caspian', 'tyrrhenian', 'sundance', 'arabian'}
TOWN_ENDINGS = {'gate': 4.4, 'shore': 4.0, 'bridge': 3.1, 'bound': 3.0,
                'port': 2.4, 'wood': 2.5, 'field': 2.4, 'more': 3.2,
                'main': 3.0, 'ward': 1.3, 'end': 1.5}
BODY_SYSTEMS = {'digestive', 'nervous', 'cardiovascular', 'lymphatic',
                'endocrine', 'respiratory', 'healthcare', 'health'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old = carry[1] if carry is not None and carry[0] == doc else b''
    raw = prefix.token_bytes[-1]
    token = prefix.token_strings[-1]
    tail = (old + raw)[-192:]
    text = tail.decode('utf-8', 'ignore')
    state = (doc, tail)
    lower = text.lower()
    m = WORD.search(lower)
    if not m:
        # Decode bytes together so a Han character split across tokens still works.
        if text != old.decode('utf-8', 'ignore'):
            if re.search(r'[东東西南北][关關]\Z', text):
                return state, 3.7
            if re.search(r'(?:中[亚亞非]|南美)\Z', text):
                return state, -3.3
            if text.endswith('北美'):
                return state, -2.0
            if text.endswith('大西洋'):
                return state, -3.6
            if text.endswith('太平洋'):
                return state, -2.5
            if text.endswith('印度洋'):
                return state, -5.5
            if re.search(r'[南北]半球\Z', text):
                return state, -5.0
        if token.strip() == '$' and re.search(r'\b(?:us|u\.s\.) ?\$\Z', lower):
            return state, -4.6
        if token == '··' and old.endswith('··'.encode()):
            return state, 0.39
        return state, 0.0
    word = m.group()
    before = lower[:m.start()]
    words = re.findall(r'[a-z]+', before)
    prev = words[-1] if words else ''
    if '-' in word:
        prev, word = word.rsplit('-', 1)
        prev = prev.rsplit('-', 1)[-1]
    direction = prev in DIRECTIONS
    value = 0.0

    if word in {'america', 'americas', 'american'}:
        value = 0.25 if word == 'american' else 0.1
        if prev == 'latin':
            value = -4.5
        elif prev in {'north', 'northern'}:
            value = -1.9
        elif prev in {'south', 'southern', 'central'}:
            value = -4.3
    elif word in {'asia', 'asian'}:
        value = -3.5 if direction else -0.2
    elif word in {'africa', 'african'}:
        value = -0.2
        if prev in {'south', 'southern'}:
            value = -0.85
        elif direction:
            value = -3.0
    elif word == 'europe' and direction:
        value = -1.6
    elif word == 'hemispheres':
        value = -3.0
    elif word == 'hemisphere':
        value = -5.2 if direction else -0.5
    elif word == 'pac' and direction:
        value = -1.7
    elif word in {'pacific', 'atlantic', 'mediterranean'}:
        value = -1.5 if prev not in {'and', 'for'} else -0.4
        if word == 'mediterranean':
            value = -0.8
        if direction or prev in {'equatorial', 'tropical'}:
            value = -2.5
    elif word == 'ocean':
        if prev == 'indian':
            value = -6.0
        elif prev in {'pacific', 'atlantic', 'arctic', 'southern'}:
            value = -2.5
    elif word == 'sea':
        value = -0.6 if prev == 'the' else 0.0
        if prev in SEAS:
            value = -4.3 if prev in {'red', 'baltic'} else -2.8
    elif word in {'east', 'eastern'} and prev in {'middle', 'near', 'far'}:
        value = -3.2
    elif word in {'east', 'west', 'eastern', 'western'} and direction:
        value = -1.2
    elif word == 'indies' and prev in {'west', 'east'}:
        value = -2.4
    elif word in {'eastern', 'western', 'southwest', 'southeast',
                  'northwest', 'northeast'}:
        value = -0.65

    # A directional word forming a local name, rather than a world region.
    town = TOWN.search(lower)
    if town:
        value = TOWN_ENDINGS[town.group(1)]

    if word == 'system':
        if prev == 'solar':
            value = -5.0
        elif prev == 'immune':
            value = -2.1
        elif prev in BODY_SYSTEMS:
            value = -1.5
    elif word == 'way' and before.endswith('milky '):
        value = -4.5
    elif word in {'equator', 'equatorial'}:
        value = -3.3 if word == 'equator' else -2.2
    elif word in {'ionospheric', 'stratospheric', 'tropospheric',
                  'magnetospheric', 'thermospheric'}:
        value = -2.8
    elif word == 'galactic':
        value = -2.1
    elif word in {'earth', 'sun', 'universe', 'planet', 'atmosphere'}:
        if prev in {'the', 'our', 'polar'}:
            value = -1.1 if word in {'atmosphere', 'planet'} else -0.7
    elif (word in {'dollar', 'dollars'}
          and (prev == 'us' or before.endswith('u.s. '))):
        value = -3.5
    elif word in {'dollar', 'dollars'} and prev in {'canadian', 'australian'}:
        value = -2.5
    elif word in {'rate', 'rates'} and prev in {'interest', 'exchange'}:
        value = -2.0
    elif word == 'policy' and prev in {'monetary', 'foreign', 'fiscal'}:
        value = -2.0
    elif word == 'membrane' and prev in {'outer', 'plasma', 'cell'}:
        value = -1.0
    elif word == 'cord' and prev == 'spinal':
        value = -1.5
    elif word in {'node', 'nodes'} and prev == 'lymph':
        value = -1.0
    elif word == 'lymphatic':
        value = -2.3
    elif word == 'cup' and prev == 'world':
        value = -1.7
    elif word == 'open' and prev in {'australian', 'french'}:
        value = -2.5
    elif word == 'zone' and prev == 'time':
        value = -0.5
    elif word == 'model' and prev == 'standard':
        value = -2.8
    elif word == 'coast' and prev == 'ivory':
        value = -1.9
    return state, value

"""Approximate a line-boundary signal using typography and local grammar.

Bare newlines are positive, especially after numbers, filename-like suffixes and chat
roles. Function words and Han text weaken that response. On tokens joining
punctuation to a newline, closing code punctuation is positive, while sentence
ends and block openers are weaker. Short lines subtract a small amount.
Document-initial tokens have a separate, coarse typography correction; this
is not an attempt to memorize their substantial token-specific variation.
"""
import regex

READS = ()
FUNCTION_WORDS = frozenset('''
    a an the of to in for with from by at as on and or but if when while
    because than that which who this these those is are was were be been
    being have has had do does did will would can could should may might not
'''.split())
HAN = regex.compile(r'\p{Script=Han}')

# How punctuation attached to a newline changes its response.
ENDING_GROUPS = (
    ('{', -0.271),                # Block opening.
    (';', 0.187),                 # Statement ending.
    ('.', -0.146),
    (',', -0.076),
    (')', 0.281),
    (']', 0.403),
    ('\"\'', 0.147),
    ('`', 0.09),
    ('/', 0.379),
    ('%', 0.519),
    ('!?。！？', -0.188),
    ('([<', -0.243),
    ('>', 0.067),
)
BLANK_LINE_ADJUSTMENTS = {
    ':': -0.159,
    '}': -0.088,
    ',': -0.176,
    '`': -0.221,
}
CHAT_ROLES = {
    'assistant': 0.277,
    'user': 0.179,
    '<tool_call>': 0.107,
    '<think>': 0.114,
    '</think>': -0.212,
    '<|im_end|>': -0.377,
}


def initial_value(token):
    word = token.strip()
    if word.lower() == 'the':
        return 2.76 if token[:1].isspace() else 2.31
    if not any(c.isalnum() for c in word):
        return 1.87 if '\n' in token else 0.97
    return 0.25 if word.isupper() else -0.22


def line_break_value(token, previous, line_length):
    body = token.split('\n', 1)[0].rstrip('\r')
    double = token.count('\n') > 1
    value = 0.154
    if not body:
        value += 0.069 - 0.04 * double
        word = previous.strip()
        if word.lower() in FUNCTION_WORDS:
            value -= 0.145
        if HAN.search(word):
            value -= 0.18
        if word.isdigit():
            value += 0.113
        if word.startswith('.') and word[1:].isalpha():
            value += 0.458  # An extension-shaped suffix.
        if '\n' in previous:
            value -= 0.069
        if previous.startswith('<'):
            value += 0.065
        value += CHAT_ROLES.get(word, 0.0)
    else:
        for characters, adjustment in ENDING_GROUPS:
            if body[-1] in characters:
                value += adjustment
                break
        if double:
            value += BLANK_LINE_ADJUSTMENTS.get(body[-1], 0.0)
        if body.endswith('*/'):
            value -= 0.339
    if body and body[-1].isspace():
        value -= 0.165
    if line_length + len(body) < 10:
        value -= 0.128
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, length, position = '', 0, 0
    else:
        _, previous, length, position = carry
    token = prefix.token_strings[-1]
    if position == 0:
        value = initial_value(token)
    elif '\n' in token:
        value = (1.0 if position == 1 else
                 line_break_value(token, previous, length))
    else:
        value = -0.003
        if token == '<tool_call>':
            value = -0.174
        elif token == '<think>':
            value = 0.10
        elif token == '</think>':
            value = -0.128
        elif token in ('<|im_end|>', '<tool_response>'):
            value = -0.07
    length = (len(token.rsplit('\n', 1)[-1]) if '\n' in token
              else min(length + len(token), 1000))
    return (doc, token, length, position + 1), value

programs.haiku:
"""layers.1.mlp.down_proj:4241 -- a line-end and document-start detector.

What the component does, as far as a short program can say:

1. Line endings in code and structured text. The component is positive on the
   newline that ends a line, most strongly when the line closes with a bracket,
   quote, semicolon or slash (")\\n", "}}\\n", ";\\n", "]\\n"), moderately on a
   bare newline after a word or number, and weakly on blank-line tokens. It is
   negative on newlines that open a block ("{\\n", " {\\n", "(\\n").
2. The first token of a document. A document in a packed row restarts attention,
   so its first token is seen with no context and its activation is a fixed
   response to that token. Articles and "to" ("The", " the", " a", "To") are
   positive, prepositions ("of", "in", "on", "into") negative, newline and
   symbol-led starts ("\\n", ";", "/*") strongly positive, special tokens
   negative.

Everything else is near zero. The program reads only the newest token and whether
it begins a new document. Its variance explained is about 0.19 on held-out
training rows; most of the remaining variance is diffuse, token-specific
and not captured by these concepts.
"""
import re

READS = ()

ARTICLES_AND_TO = {"The", " The", "the", " the", " a", " an", "To", " to", "This"}
PREPOSITIONS = {" of", " on", " in", " into", "In", " at", " it", " was", "A", " is"}
CLOSERS = ")]}\"';/`"
OPENERS = "{(["


def document_start_value(token):
    """Activation of the first token of a document, which sees no earlier context."""
    if token.startswith("<|"):
        return -0.2  # special tokens such as <|im_start|>
    if re.search(r"[\r\n]", token):
        return 2.0  # a document that starts with a newline
    if token in ARTICLES_AND_TO:
        return 1.5
    if token in PREPOSITIONS:
        return -0.7
    if re.search(r"[A-Za-z0-9]", token):
        return 0.0  # other words
    return 0.4  # other symbols and code markers


def line_end_value(token):
    """Activation of a token inside the body of a text: nonzero only on line ends."""
    if not re.search(r"[\r\n]", token):
        return 0.0
    body = token.rstrip()
    if body == "":
        return 0.17  # a bare newline or blank line
    if body[-1] in CLOSERS:
        return 0.32  # a line closed by a bracket, quote, semicolon or slash
    if body[-1] in OPENERS:
        return -0.16  # a line that opens a block
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    new_document = len(prefix.token_ids) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if new_document:
        return None, document_start_value(token)
    return None, line_end_value(token)

programs.sol:
"""Approximate structured-text responses, leaving ordinary text near zero.

Line-initial access modifiers and declaration keywords respond positively;
blank-line-separated declarations are stronger, and C++ labels are weaker.
Line-leading spaces respond negatively, fading with document progress and
familiar indentation. Escaped newlines count for code layout, but not for
this negative space response. Formatting exceptions cover opening Title:
headers, middle-dot pairs, NULs, and several document-initial cases.

These rules capture conspicuous events, not the smaller lexical residuals.
"""
import re
import math

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, '', '', 0, 0, {}, True, False)
    (_, position, first, line, breaks, indents, widths,
     physical_start, cpp) = carry
    token = prefix.token_strings[-1]
    word = token.strip()
    at_start = (not line.strip() or line.strip() in ('`', '``', '```')
                or bool(re.fullmatch(r'\s*\d+:?\s*|\s*//\s*', line)))
    value = 0.0

    if word in ('public', 'protected', 'internal'):
        if at_start:
            value = 0.20 if cpp else 0.83 + 0.11 * (breaks >= 2)
            if not token[:1].isspace():
                value -= 0.15
        elif word == 'public':
            value = 0.05
    elif word == 'private' and at_start:
        value = 0.10 if cpp else 0.27 + 0.27 * (breaks >= 2)
    elif word == 'static':
        if line.strip() in ('public', 'private', 'protected', 'internal'):
            value = 0.50
        elif at_start:
            value = 0.30
    elif word in ('func', 'export'):
        value = 0.32 if at_start else 0.0
    elif word == '@Override':
        value = 0.46

    if token and not token.strip(' ') and len(token) > 1:
        if position == 0:
            value = 0.50
        elif physical_start:
            familiarity = widths.get(len(token), 0)
            value = -0.45 * math.exp(-position / 30) * 0.4 ** indents
            value -= 0.18 / (1 + 4 * familiarity + 2 * indents)
    if token.isspace() and ('  ' in token or '\t' in token):
        indents += 1
        width = len(token.strip('\r\n'))
        widths[width] = widths.get(width, 0) + 1
    if position == 0:
        if token == 'package':
            value = -1.08
        elif token == 'def':
            value = 1.70
        elif token == ' ':
            value = 0.25
    if token == '\x00':
        value = 4.84 if position == 0 else -0.09
    if position == 1 and first == 'Title' and token == ':':
        value = 9.55
    if token == '\u00b7\u00b7':
        value = 0.92

    # Code embedded in strings can use escaped rather than actual line breaks.
    # Only real line breaks license the negative indentation response.
    for char in token:
        if char == '\n':
            physical_start = True
        elif not char.isspace():
            physical_start = False
        if char == 'n' and line.endswith('\\'):
            char = '\n'
        elif char in ('t', 'r') and line.endswith('\\'):
            line = line.rstrip('\\')
            char = '\t' if char == 't' else '\r'
        if char == '\n':
            line = ''
            breaks += 1
        else:
            line = (line + char)[-100:]
            if not char.isspace() and char != '\\':
                breaks = 0
        cpp = cpp or '#include' in line or '#pragma' in line
    return (doc, position + 1, token if position == 0 else first,
            line, breaks, indents, widths, physical_start, cpp), value

"""Approximate a ster-sensitive spelling feature, not a semantic word class.

The main response is negative for 'ster', including pieces spanning tokens.
Short fragments get a strong response; familiar or long whole words get less.
Cyrillic spellings are transliterated. Smaller rules cover er pieces, related
consonant clusters, and a decaying response on the next piece of a word.
There is also a small document-start offset and a document-initial Title: pulse.
Only the last 64 characters and document position are carried forward.
"""
import math
from functools import lru_cache
import regex as re
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()


def spelling(text):
    if re.search(r'\p{Script=Cyrillic}', text):
        return anyascii(text).lower()
    return text.lower()


@lru_cache(maxsize=20000)
def frequency(word):
    return zipf_frequency(word.lower(), 'en')


def response(token, before):
    text, previous = spelling(token), spelling(before)
    if 'ster' in text:
        left, tail = text.split('ster', 1)
        fragment = (not token[:1].isspace()
                    and (not left or len(left) == 1 and left in 'aeiouy'))
        if fragment:
            value = -4.04
            if left == 'a':
                value += 1.46
                if previous.endswith('e'):
                    value -= 4.13  # e + aster, rather than f + aster
            elif left == 'i':
                value += 1.05
            elif left in ('u', 'y'):
                value += 1.76
            value += .58 if tail == 's' else 2.56 if tail else 0.
            if previous.endswith(('l', 'w', 'o')):
                value -= .87
            if previous.endswith('st'):
                value -= .40
            return value
        rarity = min(2., max(0., 4.8 - frequency(token.strip())))
        strength = rarity * math.exp(
            -.5 * len(tail) - .4 * max(0, len(left.strip()) - 3))
        value = -.15 + strength * (
            -.21 - .35 * rarity - .91 * token.strip()[:1].isupper())
        if 'poster' in text:
            value -= 2.95 / (1 + len(text.split('poster', 1)[1]))
        return value

    if text.startswith('er') and previous.endswith('st'):
        stem = re.search(r'[a-z]+$', previous)
        word = (stem[0] if stem else '') + text
        rarity = min(3., max(0., 5. - frequency(word)))
        capital = bool(re.search(r'\b[A-Z][a-z]*$', before))
        return (-1.98 - .63 * rarity - 1.31 * capital
                + (1.51 if text not in ('er', 'ers') else 0.))

    value = 0.
    if previous.endswith('s') and text.startswith('ter'):
        value -= 1.44
    if previous.endswith('sz') and text.startswith('ter'):
        value -= 3.18  # Hungarian sz spells an s sound.
    if previous.endswith('st') and text.startswith('ler'):
        value -= 1.60
    if previous.endswith('ster') and token.isalpha():
        value -= .79
    if previous.endswith('x') and text.startswith('eter'):
        value -= 3.29
    if text in ('er', 'ers'):
        value += .04
        last = previous[-1:]
        if last and last in 'aeiou':
            value += .27
        if last == 'o':
            value += 3.15
        elif last in ('l', 'r'):
            value += .43
        elif last == 'w':
            value += .60
        elif last in ('k', 't'):
            value -= .22
    elif len(text) < 6 and 'ter' in text:
        value -= .13
    return value


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        before, position = '', 0
    else:
        _, before, position = carry
    token = prefix.token_bytes[-1].decode('utf-8', 'replace')
    value = response(token, before)
    if position == 0:
        value += .25 + .10 * token[:1].isupper()
    if position == 1 and before == 'Title' and token == ':':
        value = -6.155
    return (document, (before + token)[-64:], position + 1), float(value)

