Sentence-initial 'at/in' and 'according to' are positive; reporting verbs are
negative, especially near a named speaker's role or an institutional source.
Other rules cover captions, respectful greetings, metadata, and Vietnamese 'do'.
A short text buffer supplies context; document boundaries clear it.
"""
import re
import regex
from opencc import OpenCC

READS = ()
SIMPLIFY = OpenCC('t2s')
REPORTS = set('表示 指出 表明 预测 获悉 告诉记者 回应 解释 提醒 报道 '
              '资料显示 据了解 据悉 报道称'.split())
DECLARATIONS = set('透露 称 强调 宣布 声明 承认 坦言 显示'.split())
COMMENTARY = set('认为 介绍 分析 推荐 证明 回答 免责声明'.split())
PREPOSITIONS = set('关于 针对 面向 面对 依 依据 鉴于 按照 根据 由于 因为'.split())
CONNECTIVES = set('就 从 以 即 继 正如'.split())
SOURCES = re.compile(
    '记者|专家|学者|人士|市民|网友|委员|代表|负责人|警方|官员|部门|法院|政府|'
    '公司|机构|研究|报告|调查|统计|资料|数据|笔者|作者|主任|书记|经理|总裁|'
    '教授|先生|女士|族长|总$')
REPORTING = REPORTS | DECLARATIONS | COMMENTARY | {'说', '道'}
VIETNAMESE = re.compile(r'[ăơưđĐ\u1ea0-\u1ef9]')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    reset = carry is None or carry[0] != doc
    before = '' if reset else carry[1]
    token = prefix.token_strings[-1]
    s = token.strip()
    if regex.search(r'\p{Han}', s):
        s = SIMPLIFY.convert(s)
    first = reset or before.endswith('<|endoftext|>')
    stop = bool(re.search(r'[。！？\n][”》】）]*$', before))
    boundary = bool(re.search(r'[。！？\n，：；][”》】）]*$', before))
    value = -.066 if first and re.search('[A-Za-z]', token) else 0.

    # Small ordinary English function-word responses.
    if token == ' an':
        value -= .042
    if token == ' in':
        value -= .012

    if s == '在':
        value += .11 + (.51 if boundary else 0.)
    if s == '据' and boundary:
        value += .77
    if s == '，在':
        # Fronted clauses after an attribution or a time/discourse phrase.
        if re.search(r'(表示|指出|认为|称|表明|显示|报道|解释|介绍说)$', before):
            value += .95
        elif re.search(r'(首先|最后|此前|之后|之前|年前|年初|年|时)$', before):
            value += .60
        else:
            value += .08
    if s in PREPOSITIONS:
        value += .13
    if s in CONNECTIVES and stop:
        value += .36
    if s in {'受', '受到', '获', '授予'}:
        value += .21
    if s == '向':
        value += .15

    # Distinguish reporting from non-Chinese/technical uses of the same words.
    han_context = not before or bool(regex.search(r'[\p{Han}�”》]$', before))
    if s in REPORTS and han_context:
        value -= .84
    if s in DECLARATIONS and han_context:
        value -= .19
    if s in COMMENTARY:
        value -= .16
    if s == '说':
        value -= .14
    if s == '道':
        value -= .06
    if s in REPORTING and SOURCES.search(SIMPLIFY.convert(before[-80:])):
        value -= .17

    # Conventional headings, list/caption markers, and respectful address.
    if s == '《':
        value += .13
    if s == '、' and re.search(r'(^|\n)\s*[一二三四五六七八九十百]+$', before):
        value += .10
    if before.endswith('\n'):
        if s in {'▲', '△'}:
            value += 1.70
        if s == '◎':
            value += 1.00
    if s == '尊敬' and (first or before.endswith('\n')):
        value += .96
    if s == '的' and before.endswith('尊敬'):
        value += 1.20
    if s == ':' and (before == 'Title' or before.endswith('<|endoftext|>Title')):
        value -= 5.33

    # Vietnamese context on the current line, or the preceding line at line start.
    line = before.rsplit('\n', 1)[-1]
    if not line.strip():
        line = before.rstrip().rsplit('\n', 1)[-1]
    vietnamese_do = s.lower() == 'do' and VIETNAMESE.search(line)
    if vietnamese_do:
        value += 1.65
    elif token == ' do':
        value -= .086

    return (doc, (before + token)[-128:]), float(value)

"""Approximate a context-sensitive detector for 'to'.

Space-prefixed lowercase 'to' gives the main response. Conventional
complements such as 'have to', 'want to' and 'according to' attenuate it;
object pronouns, numbers and directional particles give stronger responses.
Only the preceding token is classified. WordNet supplies inflected forms.
Case variants, compound prepositions and Russian/Chinese destination
markers receive smaller fixed responses; other tokens receive zero.
"""
from functools import lru_cache
import wordnet

READS = ()

# Grammatical contexts, written as base words rather than inflection tables.
TO_CONTEXTS = (
    (-0.32, 'have'),                         # obligation
    (-0.07, 'want need wish try'),           # desire / attempts
    (0.14, 'according due owing equal similar adjacent relate correspond '
           'respect regard lead suppose'),  # fixed to-constructions
    (0.40, 'compare prior relative next addition reference refer'),
    (0.29, 'able unable ready easy hard difficult possible impossible '
           'necessary important enough likely unlikely willing'),
    (0.52, 'ability capacity opportunity attempt plan decision order way'),
    (0.48, 'seem appear continue begin start decide mean expect intend hope'),
    (0.35, 'be'),
    (0.98, 'go use require'),
)
TO_CONTEXTS = tuple((value, frozenset(words.split()))
                    for value, words in TO_CONTEXTS)
OBJECT_PRONOUNS = frozenset(
    'me you him her it us them myself yourself himself herself itself '
    'ourselves themselves'.split())
DIRECTION_PARTICLES = frozenset('down out off back on'.split())


@lru_cache(maxsize=4096)
def after_token(token):
    word = token.strip().lower()
    if word in OBJECT_PRONOUNS or word.isnumeric():
        return 1.62
    if word in DIRECTION_PARTICLES:
        return 2.06
    if word in ('how', 'what'):
        return 0.22
    if word in ('and', 'or', 'but', 'not'):
        return 0.91
    forms = {word, *wordnet.base_forms(word)}
    for value, roots in TO_CONTEXTS:
        if forms & roots:
            return value
    return 1.36


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token == ' to':
        if (prefix.position == 0 or
                prefix.document_ids[-1] != prefix.document_ids[-2]):
            value = 0.68
        else:
            value = after_token(prefix.token_strings[-2])
    elif token in ('To', ' To'):
        value = 0.50
    elif token.strip() == 'TO':
        value = 0.93
    elif token.endswith('-to'):
        value = 1.35
    elif token == '.to':
        value = 0.45
    elif token in (' into', ' onto', ' unto'):
        value = {' into': 0.26, ' onto': 0.63, ' unto': 1.27}[token]
    elif token.strip() in ('к', 'К'):
        value = 0.40
    elif token == '到':
        value = 0.38
    else:
        value = 0.0
    return None, value

programs.haiku:
"""Layer-1 MLP unit 4246: a "to" detector whose strength depends on the word before "to".

The unit fires on the word "to" (and "To", " TO"). It is almost silent on every other
token. How strongly it fires on "to" depends on the previous word:
  - after an auxiliary or a want/need/try verb ("have to", "want to", "need to",
    "trying to", "able to"), the "to" is an infinitive marker the model can already
    predict, and the unit stays at about zero;
  - after a copula or an adjective/noun that takes an infinitive ("is to", "way to",
    "time to", "similar to", "related to"), the unit is weak;
  - after an object pronoun, a particle or a number/punctuation ("it to", "them to",
    "back to", "down to", "out to", "2 to", "), to"), it is strongest;
  - otherwise (verbs and nouns: "going to", "used to", "applied to", "returned to") it
    is medium-strong.
Predicts that strength on each "to" and 0 elsewhere.
"""

READS = ()

TO = {" to", "To", " To", "to", " TO", "-to"}
AUX = {" have", " has", " had", " want", " wants", " wanted", " need", " needs", " trying",
       " tried", " try", " ready", " able", " unable", " how", " according", " due", " respect",
       " supposed", " like"}
COPULA = {" is", " was", " are", " were", " seem", " seems", " be", " important", " necessary",
          " difficult", " hard", " easy", " possible", " related", " equal", " similar", " leading",
          " lead", " leads", " way", " ability", " time", " opportunity"}
OBJECT = {" it", " them", " me", " him", " us", " you", " her", " back", " out", " down", " up",
          " on", " off", " away", " over", " here", " there", ",", ")", "0", "1", "2", "3", "6",
          "7", "`"}
LEVEL = {"aux": -0.06, "copula": 0.39, "object": 1.59, "other": 1.17}


def step(carry, prefix, upstream):
    if prefix.token_strings[-1] not in TO or len(prefix.token_strings) < 2:
        return carry, 0.0
    prev = prefix.token_strings[-2]
    if prev in AUX:
        kind = "aux"
    elif prev in COPULA:
        kind = "copula"
    elif prev in OBJECT:
        kind = "object"
    else:
        kind = "other"
    return carry, LEVEL[kind]

programs.sol:
"""A surface-language approximation to resource and time requirements.

Costs, impersonal 'it takes/took', duration verbs, waiting, and Chinese
expense characters get negative values. Personal-agent uses of taking
receive much smaller magnitudes.
The cost spelling also produces responses in cognates and lookalike words;
completing that spelling across a token boundary gets a larger response.
Everything else is left near zero. Only a short text tail is remembered.
"""
import re
from functools import lru_cache
import wordnet

READS = ()
HUMAN = set('i we you he she they me us him her them who'.split())
IMPERSONAL = set('it this that which these those'.split())
MODALS = set((
    "will would may might can could should shall must "
    "won't can't cannot doesn't don't didn't"
).split())
ASPECT = set('has have had is are was were be been being'.split())
ADVERBS = set('not only just also still always often never usually really'.split())
DETERMINERS = set('the a an my your his her its our their this that one'.split())
ROOTS = set('take last wait require need charge'.split())
WORDS = re.compile(r"[A-Za-z]+(?:['’][A-Za-z]+)?")
COST = re.compile(r'cost|kost|coast|cuest|côte|coû(?:t)?|кош|кос(?:т)?|каш', re.I)

@lru_cache(maxsize=8192)
def root(word):
    if word in ROOTS:
        return word
    return next((w for w in wordnet.base_forms(word) if w in ROOTS), '')

@lru_cache(maxsize=4096)
def person(word):
    kinds = wordnet.categories(word.lower())
    return word.lower() in HUMAN or kinds == {'noun.person'}


def subject(words):
    """Ignore nearby auxiliaries/adverbs, then distinguish people from 'it'."""
    for w in reversed(words[-5:]):
        q = w.lower()
        if q in MODALS | ASPECT | ADVERBS:
            continue
        if q in IMPERSONAL:
            return 'it' if q == 'it' else 'impersonal'
        if person(w) or (w.istitle() and not wordnet.parts_of_speech(q)):
            return 'human'
        return 'other'
    return 'other'


def predict(token, tail):
    w = token.strip()
    q = w.lower()
    r = ''
    if re.match(r'^(tak|took|last|wait|requir|need|charg)', q):
        r = root(q)
    if r:
        before = WORDS.findall(tail)
        prev = before[-1].lower() if before else ''
        agent = subject(before) if r in {'take', 'charge'} else ''
    if r == 'take':
        if q == 'taken':
            if prev in {'has', 'have', 'had'}:
                return -5.0 if agent in {'it', 'impersonal'} else -1.6
            return 0.25
        if q == 'taking':
            if prev in {'of', 'by', 'for', 'after', 'before', 'am'}:
                return 0.2
            return -1.4 if tail.rstrip().endswith(',') else -0.6
        if q == 'takes':
            return {
                'it': -6.8, 'impersonal': -4.7, 'human': -0.6, 'other': -2.7
            }[agent]
        if q == 'took':
            return {
                'it': -8.8, 'impersonal': -4.6, 'human': 0.0, 'other': -1.5
            }[agent]
        if prev == 'to':
            return 0.03
        if agent in {'it', 'impersonal'}:
            return -8.0 if agent == 'it' else -4.8
        if agent == 'human':
            return 0.1
        if prev in {'will', 'would', 'may', 'might', 'not'}:
            return -3.4
        return -0.3
    if r == 'wait':
        return -0.6 if q.endswith('ing') else -0.8
    if r == 'last':
        if q != 'last':
            return -0.3 if q.endswith('ing') else -2.4
        if prev in DETERMINERS or prev.endswith("'s"):
            return 0.1
        return -3.0 if prev in MODALS | {'to', 'not'} else -0.8
    if r == 'require':
        return -0.03 if q.endswith(('ed', 'ing')) else -0.3
    if r == 'need':
        return -0.08
    if r == 'charge':
        if prev in {'in', 'a', 'the', 'electric', 'point', 'positive', 'negative'}:
            return 0.05
        return -2.5 if prev in MODALS | HUMAN else -0.6

    # Cost-like spellings, including split words and cognates.
    old = re.search(r'[^\W\d_]+\Z', tail, re.UNICODE)
    stem = old.group() if old and token[:1].isalpha() else ''
    joined = stem + w
    m = COST.search(joined)
    if m and m.group().lower() == 'cuest' and m.start() != 0:
        m = None
    if m and w and w[-1].isalpha():
        before = WORDS.findall(tail)
        prev = before[-1].lower() if before else ''
        old_match = COST.search(stem)
        suffix = joined[m.end():].lower()
        if old_match and m.end() == old_match.end():
            # Most continuations stop firing, even while still in the word.
            if suffix in {'s', 'es', 'a'}:
                return -5.5
            return -0.6 if 'coast' in stem.lower() else 0.0
        if suffix not in {'', 'a', 'o', 's', 'es', 'en', 'ing', 'e'}:
            return 0.0
        if stem and m.start() < len(stem):
            spelling = m.group().lower()
            if spelling == 'coast':
                return -5.5
            if spelling in {'кос', 'каш', 'côte'} or spelling.startswith('coû'):
                return -4.0
            return -7.5
        if 'coast' in q:
            return -2.3
        if q.startswith('kost'):
            return -7.8 if q == 'kost' else -3.5
        if w.isupper():
            return -4.0
        if q.endswith('ing'):
            return -5.5
        if prev in MODALS | {'it'}:
            return -6.0
        if prev in {'this', 'that', 'which'}:
            return -4.0
        return -2.0 if q.endswith('s') else -1.6

    # Expense, consumption, saving, and need in Chinese.
    if w in {'费', '費'}:
        return -4.8
    if w in {'费用', '費用', '缴费', '繳費'}:
        return -2.2
    if w == '花了':
        return -5.8
    if w == '花':
        return -0.65
    if w == '耗':
        return -2.4
    if w == '省':
        return -1.2
    if w in {'需要', '不需要', '需', '无需', '無需'}:
        return -0.8
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = predict(token, tail)
    return (doc, (tail + token)[-100:]), float(value)

programs.haiku:
"""A lexicon for the words 'cost' and 'take' (and a few look-alikes), with a previous-word rule.

What the component responds to, from the data:
- 'take' / 'takes' / 'took' / 'taken' / 'taking' meaning 'requires time or effort', when the
  subject is a thing: 'It takes an hour' (about -8), 'that / which takes' and 'will / would /
  may take' (about -4), 'has taken' (about -1.5). After a person ('I took', 'we take', 'to
  take') it is about 0.
- 'cost' / 'costs' / 'costing' ('It costs' about -8; other uses about -2), and spellings that
  look like 'cost': 'Coast', 'Kosten', and German 'K' + 'ost' (Kostenvoranschlag, Kostroma).
- 'last' / 'lasted' meaning duration: 'will last', 'can last' (about -3); 'the last' ~0.
- A few Chinese and Japanese tokens: 费 (about -5), 費 (about -4), 費用 / 缴费 / 花费 / 耗
  (about -2.5), 省 (about -1.5), 需要 (about -0.8).
- 'Wait' / 'waiting' (about -0.8, common in reasoning text).

It does not respond to money or cost words in general: 'fee', 'pay', 'expensive', 'budget'
and 'spend' are all near 0. Everything else is 0.
"""

READS = ()

TAKE = {"take", "takes", "took", "taken", "taking"}
COST = {"cost", "costs", "costa", "coast", "kosten", "costing"}
LAST = {"last", "lasted", "lasts"}
MONEY = {
    "费": -5.0, "費": -4.0, "費用": -2.5, "费用": -2.5, "缴费": -2.5,
    "花费": -2.5, "花了": -5.0, "耗": -2.5, "省": -1.5, "需要": -0.8,
}
IT = {"it"}
THING = {"that", "which", "this"}
MODAL = {"will", "would", "may", "might", "could", "shall", "should"}
PERFECT = {"has", "have", "had", "just", "also", "not"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    prev = prefix.token_strings[-2].strip().lower() if len(prefix) > 1 else ""
    word = token.strip().lower()
    if token in MONEY:
        return None, MONEY[token]
    if word in TAKE:
        if prev in IT:
            return None, -8.0
        if prev in THING or prev in MODAL:
            return None, -4.5
        if prev in PERFECT:
            return None, -1.5
        return None, 0.0
    if word in COST:
        return None, -8.0 if prev in IT else -2.0
    if word == "ost" and prev == "k":
        return None, -8.0
    if word in LAST:
        return None, -3.0 if prev in MODAL | IT | THING | {"to"} else -0.3
    if word in ("wait", "waiting"):
        return None, -0.8
    return None, 0.0

programs.sol:
"""Sparse typesetting-syntax detector, not a general mathematics detector.

Large responses mark completed LaTeX environment/control words, TeX lengths,
and Mathematica box/list openings. Smaller rules recognize CSS lengths,
interface labels and Rust modifiers; a document's Title: header is negative.
The 120-character tail resets between documents. Unmatched tokens get zero.
"""
import re

READS = ()

# Values belong to named typesetting constructs, not token IDs.
ENVIRONMENTS = {
    'aligned': 8.3, 'align': 5.8, 'equation': 5.0,
    'array': 4.9, 'split': 10.9, 'smallmatrix': 5.3,
    'bmatrix': 1.3, 'itemize': 8.1, 'center': 7.6,
    'cases': 3.2, 'tabular': 5.0, 'widetext': 2.5,
    'figure': 0.3, 'table': 0.0,
}
COMMANDS = {
    'ensuremath': 9.6, 'nonumber': 11.8, 'phantom': 3.1,
    'centering': 6.4, 'eqno': 5.8, 'mathop': 3.1,
    'mathit': 1.6, 'scriptstyle': 3.3, 'scriptscriptstyle': 3.9,
    'mbox': 1.4, 'substack': 3.1, 'columnwidth': 2.7,
    'xymatrix': 1.1, 'infer': 2.0, 'operatorname': 0.3,
}
TEX_LENGTHS = {
    'pt': 7.2, 'pc': 3.9, 'cm': 9.3, 'mm': 13.4,
    'em': 10.2, 'ex': 8.2, 'px': 0.45,
}
BOX = (
    r'(Row|Fraction|Sqrt|Superscript|Subscript|Subsuperscript|'
    r'Underoverscript|Overscript|Underscript|Style|Form|Tag|'
    r'Interpretation)Box'
)


def predict(before, token):
    text = before + token

    # Fire when the environment name is complete, before its closing brace.
    m = re.search(r'(?:begin|end)\{([A-Za-z]+)(\*?)\Z', text)
    if m and m[1] in ENVIRONMENTS:
        if m[2]:
            return 8.6 if m[1] == 'align' else 2.3
        return ENVIRONMENTS[m[1]]

    m = re.search(r'\\([A-Za-z]+)\Z', text)
    if m and m[1] in COMMANDS:
        return COMMANDS[m[1]]
    if token.startswith('{'):
        for name, value in (('ensuremath', 2.1), ('boxed', 1.1),
                            ('mbox', 0.6), ('xymatrix', 2.9)):
            if before.endswith('\\' + name):
                return value

    # Attached TeX dimensions are much stronger than ordinary measurements.
    unit = token.lstrip()
    if re.search(r'\d\s*\Z', before):
        if token == unit and '\\' in before[-70:] and unit in TEX_LENGTHS:
            return TEX_LENGTHS[unit]
        decimal = bool(re.search(r'\.\d+\Z', before))
        if unit == 'px':
            return 2.8 if decimal else 0.6
        if unit == 'em':
            return 4.0 if decimal else 1.1

    # Mathematica's RowBox[List[...]] and related notebook expressions.
    m = re.search(BOX + r'(\[List)?(\[(?:"|F)?)?\Z', text)
    if m:
        name, is_list, opening = m.groups()
        if opening:
            if is_list:
                return {'[': 10.2, '["': 6.3, '[F': 11.1}[opening]
            return 1.2 if opening == '["' else 3.1
        if is_list:
            return 7.2
        return 3.3 if name == 'Row' else 1.0

    # Small, separate responses to familiar labels and programming modifiers.
    m = re.search(r'\b(View|Read|Learn|VIEW|READ|LEARN) (More|MORE)\Z', text)
    if m:
        return {'view': 3.8, 'read': 1.0, 'learn': 1.0}[m[1].lower()]
    if re.search(r'\bView Full(?: Document)?\Z', text):
        return 1.5 if text.endswith('Document') else 1.1
    if re.search(r'\bShow Tags\Z', text):
        return 0.75
    if text.endswith('Click to expand'):
        return 0.6
    if text.endswith('#pragma once'):
        return 1.3
    if text.endswith('#[inline'):
        return 3.2
    if text.endswith('#[derive'):
        return 0.5
    if token == 'mut' and before.rstrip().endswith('&'):
        return 1.2
    if before == 'Title' and token == ':':
        return -3.4
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    value = predict(before, token)
    return (doc, (before + token)[-120:]), value

"""Recognize short lab/label spellings, not all words containing those letters.

The strongest response is to a token completing l + ab. Whole lab names,
label abbreviations and plotting names also respond. Some competing
continuations of l are negative. Vietnamese 'lại' is a separate response.
Only the preceding token is remembered, and documents reset that memory.
