from anyascii import anyascii

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    t = anyascii(text).lower()
    p = carry[1] if carry is not None and carry[0] == doc else ''
    word = t.strip().strip('._/<>-')
    capital = text.strip()[:1].isupper()
    spaced = text.startswith(' ')
    value = 0.0

    if word == 'lab':
        if spaced:
            value = 4.5 if capital else 2.9
        else:
            value = 3.5 if text.isupper() else 6.8
    elif word == 'labs':
        value = 2.1 if spaced else 4.5
    elif word == 'label':
        if text.startswith('<'):
            value = 4.0
        elif spaced:
            value = 1.3 if capital else 0.2
        else:
            value = 1.8 if capital else 0.8
    elif word == 'labels':
        value = 0.3
    elif re.fullmatch(r'[xyz]label', word):
        value = 6.2 if text.startswith('.') else 3.6
    elif word.startswith('laborator'):
        value = 1.9 if capital else 0.8
    elif word == 'lbl':
        value = 2.5
    elif word == 'lb':
        value = 0.6
    elif word == 'matlab':
        value = 3.3
    elif word == 'matplotlib':
        value = 1.9
    elif word == 'pyplot':
        value = 5.5
    elif word == 'slab':
        value = 4.0
    elif word == 'lib':
        value = 0.2

    # Do not treat morphological suffixes such as "able" as "ab".
    if p.endswith('l'):
        single_l = re.search(r'[a-z]+$', p).group() == 'l'
        if t == 'ab':
            value += 12.0 if p.endswith('-l') else (7.8 if single_l else 5.6)
        elif t == 'abs':
            value += 6.5
        elif t.startswith('ad'):
            value -= 1.5 if single_l else 1.0
        elif t in ('ass', 'asses'):
            value -= 3.6 if t.endswith('es') else 1.7
        elif t == 'api':
            value -= 3.2
        elif t.startswith('ib'):
            value += 1.6 if t == 'ib' else 0.2
        elif t.startswith(('ob', 'eb')):
            value += 0.6 if single_l else 0.3
    elif p.endswith(('la', 'le')) and t.startswith('b'):
        value += 1.3 if t == 'b' else 0.2

    if text.strip() == 'lại':
        value = 3.3
    return (doc, t), float(value)

"""Approximate a negative response to written r-g, r-j and r-zh junctions.

Normalize alphabetic scripts by transliteration, grouping g/j/zh together.
Inside a token, use fragment length, the vowel before rg, capitalization,
and normalized spelling's English frequency to set the response. A junction
across tokens is stronger. Some response survives into a word continuation.
Reset this one-token memory at document boundaries.
"""
import re
import regex
from functools import lru_cache
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()

@lru_cache(maxsize=20000)
def spelling(s):
    # Do not interpret Chinese readings as alphabetic word fragments.
    if regex.search(r'\p{Script=Han}|\p{Script=Hiragana}', s):
        return ''
    katakana = bool(regex.search(r'\p{Script=Katakana}', s))
    s = anyascii(s.lower().replace('ž', 'g')).lower()
    if katakana:
        s = s.replace('ru', 'r')  # The vowel separating Japanese r and g.
    return re.sub('dzh|zh|j', 'g', s)

@lru_cache(maxsize=20000)
def junction(s):
    word = spelling(s).strip()
    rpos = word.find('rg')
    if rpos < 0:
        return 0.0
    if word == 'rg':
        return -4.4
    vowel = word[rpos-1:rpos] if rpos else ''
    length = len(word)
    frequency = zipf_frequency(word, 'en')
    if length == 3 and rpos == 1 and vowel in 'aou':
        word_start = s[:1].isspace() or (s.isalpha() and s.istitle())
        return -0.3 if word_start and vowel != 'u' else -2.6
    if frequency < 4:
        if vowel == 'e':
            if length <= 3:
                return -4.6
            if rpos <= 2:
                return -0.9 if rpos <= 1 else -2.0
            return -0.4 if rpos + 2 == length else -0.9
        if length > 5:
            return -0.16
        if frequency < 2:
            return -3.8 if vowel == 'o' else -0.8
        return -1.25 if length <= 3 else -0.45
    if vowel == 'a':
        return 0.0 if rpos <= 2 else -0.14
    if not s.lstrip()[:1].isupper():
        return -0.86 if length <= 5 else -0.11
    return -1.35 if vowel == 'o' and rpos > 1 else -0.08


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        prev, previous = '', 0.0
    else:
        _, prev, previous = carry
    s = prefix.token_strings[-1]
    letters = spelling(s)
    value = junction(s)
    if prev.endswith('r') and letters.startswith('g'):
        # r-g is weak when the g starts a consonant cluster or a familiar word.
        cluster = letters[1:2] in ('r', 'l')
        familiar = len(letters) > 3 and zipf_frequency(letters, 'en') >= 4
        value = -0.5 if cluster or familiar else -5.8
    base = value
    if letters[:1].isalpha() and not s[:1].isupper():
        if prev.endswith('g'):
            seed = min(previous, -4.4) if prev.endswith('rg') else previous
            fraction = 0.7 if len(letters) <= 3 else 0.2
            if letters[:1] not in 'aeiou':
                fraction = 0.15
            value += seed * fraction
        else:
            value += 0.1 * previous
    return (doc, letters, base), value

"""Approximate a compound-measurement-unit detector.

Rates (m/s, mg/L, pounds per hour) receive large positive values.
Recognizable unit-name continuations receive smaller values. Bare units
and ordinary text mostly receive zero. An independent negative response
marks the colon in a document-initial 'Title:'. Fixed response sizes
approximate the training examples; there is no token-ID lookup.
"""

READS = ()

import re
from functools import lru_cache

TIME = {}
for name, words in (
    ('second', 's sec secs second seconds 秒'),
    ('minute', 'min mins minute minutes 分钟 分鐘'),
    ('hour', 'h hr hrs hour hours 小时 小時'),
    ('day', 'day days 天 日'), ('week', 'week weeks 周 週'),
    ('month', 'month months 月'), ('year', 'yr yrs year years 年'),
):
    TIME.update(dict.fromkeys(words.split(), name))
SI = re.compile(
    r'(?:[fpnumcdhkMGTµμ]?(?:m|g|s|l|L|J|W|V|A|N|Pa|Hz|B|b|mol|Ci|'
    r'C|K|F|Ω|Wb|T|H|lm|lx|Bq|Gy|Sv|kat|M)'
    r'|rad|rev|rpm|mcg|mmHg|kgf|gf|lbf|kWh|Nm|kmh|dB|dBc|eV|cal|erg|S)\Z'
)
ENGLISH = re.compile(
    r'(?:kilo|milli|centi|micro|nano|deci)?'
    r'(?:met(?:er|re)s?|grams?|lit(?:er|re)s?|moles?|joules?|watts?)\Z'
)
OTHER = set('''foot feet inch inches mile miles mi pound pounds ounce ounces
acre acres hectare hectares ha lb lbs oz in ft yd ton tons tn tonnes t st dwt
qt gal pt tsp tbsp degree degrees cent cents dollar dollars euro euros
centime centimes rupee rupees pence byte bytes bit bits calorie calories
Å angstrom angstroms U IU unit units parts cases cells frames points atoms'''.split())
CHINESE_UNITS = set(
    '米 公尺 千米 公里 厘米 毫米 克 千克 公斤 '
    '升 公升 毫升 元 万元 萬元'.split()
)
COMPOUNDS = set('mmH mmHg Nm kWh kgf dBc kmh'.split())
WORD_END = re.compile(r'([A-Za-zµμÅΩ]+)(?:[²³⁻^0-9+-]+)?\s*\Z')

@lru_cache(maxsize=8192)
def unit(s):
    if s.lower() in TIME: return TIME[s.lower()]
    if not (SI.fullmatch(s) or ENGLISH.fullmatch(s.lower())
            or s in OTHER or s in CHINESE_UNITS):
        return None
    lower=s.lower()
    if re.fullmatch(r'[fpnumcdhkMGTµμ]?mol',s): return 'molar'
    if re.fullmatch(r'[fpnumcdhkMGTµμ]?[lL]',s):
        return 'litre' if len(s)==1 else 'small_volume'
    if re.search(r'lit(?:er|re)',lower) or s in ('升','公升','毫升'):return 'litre'
    if (re.fullmatch(r'[fpnumcdhkMGTµμ]?m',s)
            or re.search(r'met(?:er|re)',lower)
            or s in ('in','ft','yd','mi','mile','miles',
                     'foot','feet','inch','inches')):
        return 'length'
    if (re.fullmatch(r'[fpnumcdhkMGTµμ]?g',s)
            or s=='mcg' or 'gram' in lower
            or s in ('lb','lbs','oz','t','tn','dwt','st','pound','pounds',
                     'ounce','ounces','ton','tons','tonnes')):
        return 'mass'
    return 'other_unit'

# Reject fragments inside words, abbreviations, and directory paths.
def end_unit(text):
    m=WORD_END.search(text)
    if m:
        if m.start():
            preceding = text[m.start()-1]
            if preceding.isalpha() or preceding in '&_.':
                return None
        if m[1]=='in' and not re.search(r'\d',text[max(0,m.start()-8):m.start()]):
            return None
        if m.start() and text[m.start()-1]=='/':
            if not end_unit(text[:m.start()-1]):
                return None
        return unit(m[1])
    return next((unit(u) for u in CHINESE_UNITS if text.rstrip().endswith(u)),None)

# Denominators written with a slash, versus written after 'per'.
SLASH = {
    'length': 7.0, 'mass': 5.8, 'litre': 6.8, 'small_volume': 5.1,
    'molar': 9.4, 'second': 7.9, 'minute': 10.9, 'hour': 7.2,
    'day': 7.5, 'week': 5.0, 'month': 5.0, 'year': 7.3,
    'other_unit': 2.0,
}
PER = {
    'length': 2.1, 'mass': 1.9, 'litre': 4.0, 'small_volume': 1.6,
    'molar': 0.0, 'second': 3.7, 'minute': 4.3, 'hour': 3.8,
    'day': 1.7, 'week': 3.2, 'month': 3.6, 'year': 2.1,
    'other_unit': 0.4,
}


def predict(before, token):
    s = token.strip()
    if before == 'Title' and token == ':':
        return -14.15
    numerator = end_unit(before)
    if re.search(r'\b(?:wt|vol)\.?$', before.rstrip()):
        if s in ('/v', '/w', '%'):
            return 5.5
    if s.lower() == 'per':
        return 3.9 if numerator else 0.3

    if '/' in token:
        left, denominator = token.rsplit('/', 1)
        n = end_unit(before + left)
        kind = unit(denominator.strip())
        if n and kind:
            return SLASH[kind]
        if n and not denominator.strip():
            return 5.0 if n == 'mass' else 3.0
        if n and denominator in 'fpnuµμcdhkMGT' and len(denominator)==1:
            return 4.0
        # Long time denominators also count objects, not just SI quantities.
        if kind in ('day', 'week', 'month', 'year', 'minute', 'hour'):
            if not re.search(r'[/_]', before[-30:]) and re.search(r'\w$', before):
                return 4.5
        return 0.0

    previous = WORD_END.search(before)
    prev = previous[1] if previous else ''
    kind = unit(s)
    if kind:
        if (kind in TIME.values() and prev == 'a'
                and re.search(r'\d|once|twice', before[-40:])):
            return 3.5
        if before.endswith(('平方', '立方')):
            return 4.5
        if prev.lower() == 'light' and kind == 'year':
            return 4.5
        if (prev in ('in', 'to') and re.search(
                r'\b(?:units?|measured|length|distance|speed|convert)\b', before)):
            return 1.6
        if re.search(r'/\s*$', before):
            if end_unit(before.rstrip()[:-1]):
                return {'length': 8.3, 'other_unit': 5.0}.get(
                    kind, SLASH[kind])
            if kind in TIME.values() and re.search(r'[$€£¥₹].*\d', before):
                return 4.5
            return 0.0
        if re.search(r'\b[Pp]er\s*(?:(?:cubic|square|metric)\s*)?$', before):
            return PER[kind]
        if prev in ('N', 'W', 'erg') and kind in ('length', 'second'):
            return 4.5
    if s in ('cubic', 'square', 'metric') and re.search(r'\bper\s*$', before):
        return 1.5

    # Product notation, or a unit word split between tokens.
    if s[:1] in ('.', '*', '·', '⋅', '-'):
        if s[1:].islower() and unit(s[1:]) and numerator:
            return 1.4
    if s and not token[0].isspace() and previous:
        whole = prev + s
        if whole in COMPOUNDS:
            return 4.2
        if SI.fullmatch(whole):
            if whole.endswith('mol'):
