            if prev in ('µ', 'μ'):
                return 1.6
            if '/' in before[-5:]:
                left = before.rsplit('/', 1)[0]
                return 2.1 if end_unit(left) else 0.0
            return 0.2
        if unit(whole):
            return 1.2 if len(s)>1 else 0.8
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = predict(before, token)
    return (doc, (before + token)[-80:]), float(value)

