    elif w in ('ric', 'rica', 'rico', 'ricardo', 'rik', 'rique'):
        value = -1.0 if attached else -3.6
        if attached and word.endswith('en'):
            value = -14.0 if word == 'en' else -8.5
        elif attached and word.endswith('d'):
            value = -5.0
    elif w in ('eric', 'erik', 'enrique', 'rick'):
        if w == 'eric':
            value = -0.5 if attached else -2.3
        else:
