    'ff': 1.916, 'n': .227, 'm': .073, 't': -4.448,
    's': -1.363, 'se': -5.156, 'i': -5.334, 'e': -2.412,
    'other': -.331,
}
# Letter immediately before r; bare r has the default strength.
ONSET = {
    'r': .952, 'b': .859, 'c': 2.103, 'k': .706,
    'g': .056, 'p': .957, 't': .121, 'd': .271,
    'vowel': .201, 'other': .135,
