def ending_class(after):
    if not after:
        return 'bare'
    if after[:2] in {'ng', 'ff', 'se'}:
        return after[:2]
    if after.startswith(('k', 'ck')):
        return 'k'
    first = 's' if after[0] == 'z' else after[0]
    return first if first in {'g', 'n', 'm', 't', 's', 'i', 'e'} else 'other'


