    doc, current = prefix.document_ids[-1], prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        previous, position = '', 0
    else:
        _, previous, position = carry
    value = spelling_response(previous, current)
    if position == 1 and previous == 'Title' and current == ':':
        value = 6.7
    return (doc, current, position + 1), float(value)

