"""v11: spelling rules for the 'ru' sound inside words, Latin and Cyrillic.

Acts on the letters of the word so far (carry), for word-internal pieces (no leading space):
  - a piece right after 'cru' (recrut-, accru-, cruis-): strongly negative;
  - 'ru' right after a 'c' (cru spelled across tokens): strongly negative;
  - a 'u' right after 'r', by the letter that follows it in the piece:
      g (rug, brug): strongly positive; k/c/f/n/l/x/y (ruck, rung, ruff): weakly positive;
      s/t/e/i/a or nothing (rus, rut, rue, rui, ru): negative.
  - Cyrillic spellings: рут, крут, and ус after р: negative.
Whole words with a leading space: recruit-, accrued, cruise, crude (negative); rug, rugby
(positive); ' ru' (negative).
"""
READS = ()

RECRUIT_WORDS = {"recruit", "recruited", "recruits", "recruitment", "recruiting", "accrued",
                 "accrual", "cruise", "cruiser", "cruising", "crude", "cru", "bru", "ruth", "rut"}
RUG_WORDS = {"rug", "rugby"}

def _letters(s):
    return "".join(ch for ch in s.lower() if ch.isalpha())

def step(carry, prefix, upstream):
    # carry: the letters of the current word so far (original script, lowercase)
    prev = carry or ""
    if prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        prev = ""
    s = prefix.token_strings[-1]
    L = _letters(s)
    value = 0.0
    if s.strip().isalpha():
        if not s.startswith(" "):
            if L and not L.isascii():
                if L in ("рут", "крут"):
                    value = -3.3
                elif L == "ус" and prev.endswith("р"):
                    value = -3.2
            elif prev.endswith("cru"):
                value = -4.0
            elif prev.endswith("c") and L.startswith("ru"):
                value = -3.0
            elif prev.endswith("r") and L.startswith("u"):
                second = L[1:2]
                if second == "g":
                    value = 3.0
                elif second in ("k", "c", "f", "n", "l", "x", "y"):
                    value = 0.5
                elif second in ("s", "t", "e", "i", "a", ""):
                    value = -1.3
            elif L in ("ru", "rut", "ruth", "rus", "rue", "ruz"):
                value = -1.5
        else:
            if L in RECRUIT_WORDS:
                value = -3.5
            elif L in RUG_WORDS:
                value = 2.0
            elif L == "ru":
                value = -1.8
    new_carry = prev + L if (s.strip().isalpha() and not s.startswith(" ")) else L
    return new_carry, value

