"""A negative signal while a Unicode character is unfinished between tokens.

Keep only the UTF-8 decoder's pending bytes. Whole characters predict nearly
zero, even when their bytes are split across tokens. An unfinished character
predicts a negative pulse, usually larger for an intermediate byte-only token
than for a fragment sharing its token with whitespace or complete text. Broad
script guesses adjust its size. These are rough averages, not token lookups.
Smaller fluctuations on ordinary text are deliberately left unmodelled.
"""
import codecs
from functools import lru_cache
import regex

READS = ()


@lru_cache(maxsize=4096)
def character_family(fragment):
    width = 2 if fragment[0] < 0xE0 else 3 if fragment[0] < 0xF0 else 4
    # The first bytes delimit a range of possible Unicode characters.
    bounds = ''.join(
        (fragment + bytes([fill]) * (width - len(fragment))).decode(
            'utf8', 'ignore')
        for fill in (0x80, 0xA0, 0xBF)
    )
    for script in ('Hangul', 'Hiragana', 'Katakana', 'Han', 'Latin',
                   'Greek', 'Cyrillic', 'Hebrew', 'Arabic'):
        if regex.search(r'\p{Script=' + script + '}', bounds):
            return 'Kana' if script in ('Hiragana', 'Katakana') else script
    return 'private' if regex.search(r'\p{Co}', bounds) else 'other'


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old = b'' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_bytes[-1]
    data = old + token
    _, consumed = codecs.utf_8_decode(data, 'replace', False)
    pending = data[consumed:]
    value = 0.002
    if pending:
        family = character_family(pending)
        if len(pending) > len(token):
            value = -3.6 if family == 'private' else (
                -5.1 if pending[0] >= 0xF0 else -6.7)
        else:
            before = token[:-len(pending)]
            if before.strip():
                value = -2.4 if family == 'Hangul' else -1.7
            elif before:
                first_byte_only = len(pending) == 1 and pending[0] >= 0xE0
                if family == 'Hangul':
                    value = -3.3 if first_byte_only else -4.1
                elif family == 'Han':
                    value = -1.5 if first_byte_only else -2.0
                elif family == 'private':
                    value = -1.0 if first_byte_only else -1.9
                else:
                    value = {
                        'Latin': -3.1, 'Cyrillic': -3.1, 'Arabic': -3.0,
                        'Greek': -1.3, 'Kana': -1.3,
                    }.get(family, -2.0 if first_byte_only else -1.6)
            else:
                value = {
                    'Han': -4.1, 'Hangul': -2.1, 'Hebrew': -4.1,
                    'Arabic': -3.0, 'Latin': -3.1, 'Cyrillic': -3.1,
                    'Greek': -1.5, 'private': -1.1,
                }.get(family, -1.8 if pending[0] < 0xE0 else -2.5)
                if pending[0] >= 0xF0:
                    value = -5.1
    return (doc, pending), value

