The main positive responses mark additive constructions and accompaniment,
including several language equivalents. A second family is 'swell' and
'swollen', including the Han characters 肿/腫. 'Hell' is negative.
Unmatched tokens get zero; more idiosyncratic spelling effects are omitted.
Carry recent text and two bytes, resetting at document boundaries.
"""
import re

READS = ()
SWELLING_HAN = tuple(c.encode("utf-8") for c in "肿腫")

# Conjunctions/adverbs meaning 'also' or 'as well as'.
ADDITIVES = {
    'sowie': 5.7,
    'également': 1.7,
    'också': 2.4,
    'serta': 1.5,
    'oraz': 0.9,
    'także': 1.8,
    'też': 2.2,
}

# The last word of a multiword additive construction.
PHRASES = {
    ('as', 'well'): 8.0,
    ('well', 'as'): 5.5,
    ('así', 'como'): 11.5,
    ('ainsi', 'que'): 8.5,
    ('а', 'также'): 7.2,
    ('cũng', 'như'): 8.5,
