def response(s, tail):
    w = s.strip().lower()
    match = re.search(r'(\w+)\s*$', tail.lower())
    prev = match[1] if match else ''
    # Spaces separate words; this avoids matching name suffixes like Roswell.
    if s[:1].isspace():
        if (prev, w) in PHRASES:
            return PHRASES[prev, w]
        if w in ADDITIVES:
            return ADDITIVES[w]
        if w == 'также':
            return 0.7
        if w == 'auch':
            if prev == 'als':
                return 9.0
            if prev in {'aber', 'wie'}:
                return 3.5
            return 1.5 if prev == 'sondern' else 0.35
        if w == 'with':
            if prev == 'along':
                return 3.8
            if prev == 'coupled':
                return 2.0
            if prev in {'together', 'combined', 'combination', 'paired', 'tandem'}:
                return 1.0
            if prev in {'conjunction', 'mixed', 'collaboration'}:
                return 0.5
        if w == 'by':
            if prev == 'joined':
                return 4.5
            if prev in {'followed', 'separated', 'accompanied', 'surrounded',
                        'connected', 'complemented', 'topped'}:
                return 2.9
            if prev in {'supported', 'backed', 'aided', 'assisted'}:
                return 1.0
        if w in {'swell', 'swollen', 'swelling', 'swelled'}:
            return 2.8
        if w == 'hell':
            return -4.6
    if prev == 'sw' and w in {'elling', 'elled'}:
        return 6.5 if w == 'elling' else 5.5
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, old_bytes = '', b''
    else:
        tail, old_bytes = carry[1:]
    s = prefix.token_strings[-1]
    value = response(s, tail)
    chunk = prefix.token_bytes[-1]
    recent = old_bytes + chunk
