import re

READS = ()
NUMBER = re.compile(r'([0-9]+)(?:\.([0-9]*))?\Z')


def zero_value(text, initial):
    if initial:
        return -1.68
    number = NUMBER.search(text)
    if number:
        integer, fraction = number.groups()
        digits = integer if fraction is None else fraction
        zeros = len(digits) - len(digits.rstrip('0'))
        if fraction is not None and not digits.strip('0'):
            if not integer.strip('0'):
                return 4.3 if zeros >= 3 or len(integer) > 1 else 2.8
            if integer == '1':
                return 1.5
            return 1.9 if integer == '3' else 0.95
        if not digits.strip('0'):
            if text[:number.start()].endswith(','):
                return 0.58 if zeros == 1 else -0.2
            return 3.5
        if zeros >= 3:
            return min(3.2, 1.4 + 0.5 * (zeros - 3))
        return 1.3 if digits.endswith('3') else -0.03
    if text[-1].isalpha():
        return 2.6
    if text[-1] == '_':
        return 1.8
    if text[-1] == '.':
        return 1.7
    if text[-1] == '-':
        return 2.4 if len(text) > 1 and text[-2].isalpha() else 0.85
    return 0.8


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        text, initial = '', True
    else:
        text, initial = carry[1:]
    token = prefix.token_strings[-1]
    word = token.strip()
    value = 0.0
