"""layers.1.mlp.down_proj:4260 -- a "introducing notation" detector.

The component goes negative on the word that announces a new symbol, name or
shorthand in mathematical writing: "Let me DENOTE the ...", "we CALL this ...",
"for SIMPLICITY, ...", "... WHERE ...", "\\LABEL{eq}", "HEREINAFTER", "NOTATION".
It is most negative when the defining verb follows a first-person or "let's"
subject ("me", "we", "'s"); "let" in everyday prose ("let it cure") is near zero.
A few words in the ordinary sense of "refer" / "merely" are slightly positive.

Largest artifact: the colon in "Title:" right after a document break
(<|endoftext|>Title:) gives about +19.8.

Everything else is predicted as 0.
"""

READS = ()

# Typical activation of the word that introduces a symbol or name.
NAMING = {
    "denote": -5.0, "denotes": -2.0, "denoted": -2.5, "oted": -2.5,
    "hereinafter": -5.0, "hereafter": -4.0, "inafter": -4.0, "nonumber": -6.0,
    "simplicity": -4.0, "notation": -2.0, "nomenclature": -3.0,
    "terminology": -2.0, "abbreviated": -2.0, "subscript": -1.5,
    "herein": -0.9, "wherein": -1.0, "clarity": -1.0, "convenient": -0.8,
    "convenience": -1.0, "omitted": -0.9,
}
# Verbs that introduce a definition: mildly negative alone, strongly after a subject.
DEFINING = {
    "call": -0.6, "let": -0.5, "write": -0.5, "assume": -0.85, "suppose": -0.6,
    "define": -0.65, "consider": -0.45, "set": -0.15, "label": -0.8,
    "represented": -0.7, "say": -0.2,
}
SUBJECTS = {"me", "we", "us", "i", "'s", "’s"}   # "Let me", "we", "Let's"
MATH_PUNCT = {"$", ")", "$,", "),", ":", "$$", "$."}  # punctuation closing a formula
# Nouns and adverbs of notation and reference.
SYMBOLS = {
    "variables": -0.6, "variable": -0.25, "coordinates": -0.75, "coordinate": -0.65,
    "indices": -0.6, "symbols": -0.6, "symbol": -0.4, "language": -0.5,
}
WHERE = {"where": -0.4, "here": -0.3}
REFER = {"refer": 0.3, "refers": 0.3, "referred": 0.4, "merely": 0.4, "simply": 0.3,
         "interested": 0.3}


def word_so_far(strings):
    """The alphabetic word ending at the newest token, and the token before it."""
    start = len(strings) - 1
    while start > 0 and not strings[start].startswith(" ") and strings[start - 1].isalpha():
        start -= 1
    word = "".join(s.strip() for s in strings[start:]).lower()
    before = strings[start - 1].strip().lower() if start > 0 else ""
    return word, before


def step(carry, prefix, upstream):
    s = prefix.token_strings
    if len(s) >= 3 and s[-1] == ":" and s[-2] == "Title" and s[-3] == "<|endoftext|>":
        return carry, 19.8
    word, before = word_so_far(s)
    value = 0.0
    if word in NAMING:
        value = NAMING[word]
    elif word == "label" and before == "\\":
        value = -3.5
    elif word in DEFINING:
        value = -2.5 if before in SUBJECTS and word != "set" else DEFINING[word]
    elif word in SYMBOLS:
        value = SYMBOLS[word]
    elif word == "where":
        value = -1.5 if before in MATH_PUNCT else -0.4
    elif word in WHERE:
        value = WHERE[word]
    elif word in REFER:
        value = REFER[word]
    return carry, float(value)

