"""Approximate a sparse, polysemantic lexical-modifier signal.

English weak-degree adverbs are strongly positive; selected scarcity,
emphatic, probability and manner expressions have smaller responses. Other
English -ly adverbs get a weak fallback. Split endings are recognized using
an unfinished word, and a preceding modal boosts probability expressions.

The additional cues are explicit: positive East Asian reciprocal/weak-degree
expressions and repeated middle dots; negative Chinese intensifiers, age or
long-duration words, and Japanese とも. Age compounds such as 中年 get stronger
negative values than calendar-year uses. Selected year markers after digits
are positive, as are initial three-space indentation and Java package-com
prefixes.
State resets between documents.
These are lexical tendencies, not a full grammatical analysis.
"""
import re
from functools import lru_cache
import wordnet

READS = ()

WEAK_DEGREE = {'slightly', 'somewhat'}
SCARCITY = {'barely', 'hardly', 'scarcely'}
EMPHATIC = {
    'highly', 'deeply', 'considerably', 'incredibly',
    'wonderfully', 'terribly', 'hugely', 'utterly',
}
CERTAINTY = {'probably', 'certainly', 'surely'}
PARTIAL = {'partly', 'partially', 'nearly'}
MANNER = {'poorly', 'badly', 'closely', 'slowly'}


@lru_cache(maxsize=32768)
def lexical(text):
    w = text.strip().lower()
    if w in WEAK_DEGREE:
        return 2.5
    if w in SCARCITY:
        return 1.4
    if w in EMPHATIC:
        return 1.3
    if w in CERTAINTY:
        return 0.75
    if w in {'likely', 'possibly'}:
        return 0.3
    if w in {'very', 'normally', 'usually', 'always'}:
        return 0.18
    if w in {'mildly', 'moderately'}:
        return 1.1
    if w in {'minimally', 'unduly'}:
        return 2.1
    if w in PARTIAL:
        return 0.65
    if w in MANNER:
        return 0.6
    if w in {'singly', 'doubly', 'triply'}:
        return 2.0
    if w in {'互相', '相互', '彼此'}:
        return 2.3
    if w == '互':
        return 1.4
    if w == '서로':
        return 1.4
    if w == '稍微':
        return 2.3
    if w == '少し':
        return 1.0
    if '非常' in w or w in {'十分', '特别', '特別', '相当', '相當'}:
        return -1.65
    if w == 'とも':
        return -3.0
    if w == '青年':
        return -3.3
    if w in {'少年', '童年', '老年', '晚年', '多年', '百年'}:
        return -1.0
    if text and set(text) == {'·'} and len(text) > 1:
        return 0.55
    if re.fullmatch('[a-z]+', w) and w.endswith('ly'):
        if 'adverb' in wordnet.parts_of_speech(w):
            return 0.08
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, history = '', ''
    else:
        _, previous, history = carry
    text = prefix.token_strings[-1]
    value = lexical(text)
    # A split-off adverb ending still belongs to the word being completed.
    if re.fullmatch('[A-Za-z]+', text) and previous:
        joined = previous + text
        if text.lower().endswith('ly'):
            value = lexical(joined)
            if text.lower() == 'ly' and value == 0.08:
                value = 0.7
        tail = joined[-64:]
    else:
        match = re.search('[A-Za-z]+$', text)
        tail = match.group()[-64:] if match else ''
    # Probability after a modal: 'can probably', 'could certainly', etc.
    w = text.strip().lower()
    if w in CERTAINTY and previous.lower() in {
        'can', 'could', 'should', 'would', 'will', 'may', 'might', 'must',
    }:
        value = 1.8
    if w == 'com' and previous.lower() == 'package':
        value = 1.1
    if text == '   ' and not history:
        value = 1.42
    # Year markers after digits differ from nonnumeric compounds.
    if text in {'年', '年の', '年に'}:
        value = 0.18 if history[-1:].isdigit() else -1.0
    if w in WEAK_DEGREE and previous.lower() == 'only':
        value *= 0.5
    # Age stages, as distinct from calendar years.
    if text.startswith('年') and history.endswith('中'):
        value = -6.0
    elif text.startswith('年') and history.endswith(('高', '熟', '壮', '壯')):
        value = -3.5
    elif w == '青年' and history.endswith('中'):
        value = -5.0
    return (doc, tail, (history + text)[-24:]), value

