"""Component layers.1.mlp.down_proj:4261: an English degree/hedging-adverb detector.

What it does
- Fires (positively) on English adverbs that grade how much a property holds, the kind that
  sit in front of an adjective or participle ("is somewhat late", "slightly high",
  "highly significant", "partly intended", "probably correct"). The size depends on the
  word: "somewhat" and "slightly" are strongest, "highly"/"considerably"/"deeply" are
  medium, "probably"/"certainly"/"nearly" are weaker, and "likely"/"usually"/"very" are faint.
- Fires negatively on Chinese words for "very" or "especially" (十分, 非常, 特别, 相当, ...)
  and on the word 青年 ("youth"). These are the component's largest negative values.
- Fires positively on the reciprocal words 互相, 相互, 彼此 and 서로 ("each other / mutually").
- Everything else predicts 0. The diffuse small activations on ordinary tokens are not modelled.

Why: the component's largest values sit on these words, and the list is a readable
description of which adverbs it responds to. The values are the per-group means measured on
training text, so a token in a group is predicted at that group's typical activation.

Main logic: look at the newest token only. Its group sets the value; no context is used
(an earlier version that dropped degree adverbs after "will" or "can" did no better, so it
was removed).
"""

READS = ()

# English degree/hedging adverbs, grouped by typical activation (strongest first).
STRONG = {" somewhat", " slightly", " doubly"}
MEDIUM = {" highly", " considerably", " deeply", " terribly", " wonderfully", " incredibly", " barely",
          " badly", " hardly", " mildly", " partly", " severely", " moderately", " poorly", " hugely"}
WEAK = {" probably", " certainly", " equally", " partially", " totally", " specially", " nearly",
        " greatly", " closely", " slowly", " surely", " possibly"}
FAINT = {" mostly", " genuinely", " normally", " thoroughly", " likely", " usually", " particularly",
         " especially", " very", " extremely", " fairly", " intensely", " strongly"}
NEGATIVE_FULLY = {" fully", " rarely"}

# Chinese words for "very"/"especially" and the word for "youth": negative.
CHINESE_VERY = {"十分", "非常", "特别", "特別", "相当", "完全", "尤为", "全力", "大力", "空前", "同等"}
YOUTH = {"青年"}

# Reciprocal words, "mutually / each other": positive.
RECIPROCAL = {"互相", "相互", "彼此", "互", "서로"}


def step(carry, prefix, upstream):
    """Predicted activation at the newest token of the prefix."""
    tok = prefix.token_strings[-1]
    if tok in STRONG:
        return None, 2.5
    if tok in MEDIUM:
        return None, 1.2
    if tok in WEAK:
        return None, 0.6
    if tok in FAINT:
        return None, 0.2
    if tok in NEGATIVE_FULLY:
        return None, -0.2
    if tok in CHINESE_VERY or tok in YOUTH:
        return None, -2.0
    if tok in RECIPROCAL:
        return None, 2.0
    return None, 0.0

"""Definition-seeking detector. The component is active where the text is about to
define, explain or name the meaning of a term: the question "What is/are ...?", the
preposition that follows a word of definition or explanation ("definition of", "meaning
of", "difference between", "more about", "know about"), the word "so-called", and words of
definition or terminology themselves. It is negative inside computational questions, such
as the "the" in "What are the prime factors".
"""
READS = ()

# words that name, ask about, or introduce a definition, concept or term
CUE = {
    "definition": 1.0, "definitions": 1.5, "terminology": 1.5, "term": 0.6, "terms": 0.4,
    "concept": 0.5, "concepts": 0.5, "defined": 0.4, "defines": 1.0, "define": 0.3,
    "meaning": 0.4, "means": 0.35, "explain": 0.45, "explanation": 0.4,
    "introduction": 0.5, "overview": 0.5, "called": 0.45, "detail": 0.6, "what": 0.2,
}
# after "what": the verb or article that opens "What is ... ?" / "What are ... ?"
AFTER_WHAT = {"is": 2.5, "are": 2.1, "a": 2.7, "an": 1.8, "does": 0.9, "makes": 1.2, "'s": 0.9, "’s": 0.9}
# words after which "what" starts a definitional question ("know what it means")
WHAT_AFTER = {"know", "about", "on", "of", "tell", "explain", "understand"}
# words of definition, explanation or topic; the preposition after them introduces the topic
FRAME = {
    "definition": 2.9, "explanation": 3.0, "concept": 2.0, "meaning": 1.7, "overview": 1.5,
    "interpretation": 1.3, "description": 1.3, "background": 1.3, "summary": 0.9,
    "examples": 0.8, "example": 0.7, "idea": 0.6, "review": 0.6, "info": 0.7,
    "information": 0.5, "types": 0.5, "purpose": 0.5, "history": 0.4, "importance": 0.4,
    "difference": 0.9, "know": 0.9, "more": 0.9, "talk": 0.8, "talks": 0.8, "learn": 0.4,
}
PREPS = {"of", "about", "between", "on"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    prev = prefix.token_strings[-2].strip().lower() if len(prefix) > 1 else ""
    prev2 = prefix.token_strings[-3].strip().lower() if len(prefix) > 2 else ""
    value = CUE.get(word, 0.0)
    if word == "what" and prev in WHAT_AFTER:
        value = 1.2
    if prev == "what" and word in AFTER_WHAT:
        value = AFTER_WHAT[word]
    if prev2 == "what" and prev in ("is", "are") and word == "the":
        value = -1.3
    if word in PREPS and prev in FRAME:
        value = FRAME[prev]
    if word == "called" and prev in ("-", "so"):
        value = 2.5
    if word == "as" and prev in ("known", "defined"):
        value = 0.6
    return None, value

programs.sol:
"""A partial lexical and grammatical predictor.

Quantity, dimension, space and time words receive positive baselines.
Local constructions distinguish 'much' from 'how much', 'well' from
'as well', and heuristic temporal/clausal uses of 'since', plus
multiword preposition beginnings. Unicode rules are coarse fallbacks;
this does not attempt to reproduce all of the component's lexical detail.
"""
from functools import lru_cache
import regex
import unihan
import inflect

READS = ()
# Named word classes, with training-estimated contributions.
SMALL_NUMBERS = ' '.join(inflect.engine().number_to_words(n)
                         for n in range(2, 11))
CLASSES = (
    ('universal quantifiers', .222, 'all every'),
    ('exhaustive coverage', .129, 'all every each whole'),
    ('amount', .169, 'much many little'),
    ('unity', .174, 'one'),
    ('comparison', -.098, 'more less most least'),
    ('dimension', .351,
     'long short high low wide narrow deep shallow tall thick thin'),
    ('size', .147, 'large small big great huge tiny'),
    ('distance', .190, 'far near close'),
    ('relative part', .202, 'back side end part top bottom front middle edge'),
    ('compass', .251, 'north south east west'),
    ('path', .088,
     'over under along across through around into down up out off away'),
    ('time and intervals', .240,
     'time day days week weeks month months year years night nights'),
    ('temporal adverb', .218, 'today once ever always soon'),
    ('temporal link', .047, 'since before after until while when'),
    ('evaluation', .065, 'well good bad better best'),
    ('intensification', -.143, 'really actually even'),
    ('degree', .059, 'very quite so too rather'),
    ('integers two through ten', -.060, SMALL_NUMBERS),
    ('negation', -.055, 'not no never none'),
)
CLASSES = tuple((name, weight, frozenset(words.split()))
                for name, weight, words in CLASSES)
SCALE_WORDS = frozenset(
    'much many little long short high low wide narrow deep shallow tall thick thin '
    'far near close right left straight back side end part top bottom front middle '
    'edge time day days week weeks month months year years night nights '
    'well good bad better best one'.split())
DEGREE_SENSITIVE = next(words for name, _, words in CLASSES
                        if name == 'dimension') | {'much', 'well', 'far'}
COPULA = frozenset('is are was were be been being'.split())
DEGREE = frozenset('how so too very pretty quite'.split())

@lru_cache(maxsize=80000)
def lexical(token):
    s = token.strip()
    w = s.lower()
    value = .007
    for _, weight, words in CLASSES:
        if w in words:
            value += weight
    if regex.search(r'\p{Script=Han}', s):
        value += .043
        if len(s) == 1:
            value += .246 * max(0, 12-(unihan.strokes(s) or 12))/12
    if regex.search(r'\p{Script=Arabic}', s):
        value += .105
    if s.startswith(('ال', 'وال', 'بال', 'لل')):
        value += .356
    if regex.search(r'[\p{Hiragana}\p{Katakana}\p{Hangul}]', s):
        value += .100
    if '\ufffd' in s:
        value += .074
    if s in ('text', 'math', 'mathrm', 'mathbf', 'display',
             'displaystyle', 'begin', 'end', 'aligned'):
        value += .163
    if s and set(s) == {'·'} and len(s) > 1:
        value -= .505
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_bytes[-1].decode('utf-8', errors='replace')
    if carry is None or carry[0] != doc:
        age, previous = 0, ''
    else:
        age, previous = carry[1]+1, carry[2]
    w, p = token.strip().lower(), previous.strip().lower()
    value = lexical(token)
    if w in SCALE_WORDS and p in COPULA:
        value += .180
    if w in DEGREE_SENSITIVE and p in DEGREE:
        value -= .220

    # Degree words and their conventional constructions.
    if w == 'every':
        value = .64
    elif w == 'well':
        value = -.075 if p == 'as' else .05 if p == 'very' else .53
    elif w == 'much':
        if p in ('how', 'pretty'):
            value = -.35
        elif p in ('as', 'so', 'very'):
            value = .09
        else:
            value = .23 if p in ('too', 'quite') else .88
    elif w == 'since':
        temporal = token == ' since' and p != 'but' and not p.endswith(',')
        value = .56 if temporal else .12
    elif w == 'right' and token.startswith(' '):
        value = .08 if p in ('the', 'to') else .62 if p in COPULA else .43
    elif w == 'far':
        if p in ('so', 'thus', 'how'):
            value = -.22
        else:
            value = .45 if p == 'as' else .22 if p == 'too' else .65
    elif w == 'one' and p in ('only', 'least'):
        value = -.03
    elif w == 'time' and p in ('first', 'every', 'same'):
        value = .10 if p == 'same' else -.10

    # Prefixes of familiar multiword expressions; no future token is read.
    if w == 'of' and p == 'out':
        value = 1.15
    elif w == 'part' and p == 'as':
        value = .79
    elif w == 'way' and p == 'by':
        value = .82
    elif w == 'other' and p in ('in', 'or'):
        value = .40 if p == 'in' else -.29
    elif w == 'as' and p in ('well', 'far', 'same'):
        value = -.22
    elif w in ('st', 'nd', 'rd', 'th') and p.isdecimal():
        value += .132

    if age == 1:
        value += .093
    elif 2 <= age <= 32:
        value += .093/age
    return (doc, age, token), float(value)

"""List-label punctuation, rather than ordinary sentence punctuation.

Recognize short alphabetical, numeric and small Roman labels. Give larger values
at line starts and after questions, with the strongest responses to the
first few alphabetical choices. Suppress function-call-like parentheses.
The state is only a short text tail, reset at document boundaries.
"""
import re

READS = ()
LABEL = re.compile(
    r'(?<![\w.])([A-Za-z]|[0-9]{1,4}|[ivxIVX]{1,5}|[一二三四五六七八九十])$'
)


def marker(before, token):
    if not token or token[0] not in '.)．:':
        return 0.0
    match = LABEL.search(before)
    if not match:
        return 0.0
    label = match[1]
    lead = before[:match.start()]
    line_start = not lead.split('\n')[-1].strip(' \t*#>•-+([（')
    opening = bool(re.search(r'(?:^|[^\w])[(（]$', lead))
    if token.startswith(')') and re.search(r'[\w}\]]\($', lead):
        return 0.0
    question = '?' in before[-160:] or '？' in before[-160:]
    after_stop = bool(re.search(r'[?:：]\s+$', lead))
    value = 0.0
    if len(label) == 1 and label.isascii() and label.isalpha():
        rank = ord(label.lower()) - ord('a')
        if rank < 5:
            decay = 1 + .23 * rank
            if line_start:
                if opening:
                    value = (4.8 if label.isupper() else 2.8) / decay
                else:
                    value = (5.8 if label.isupper() else 4.5) / decay
                    if token.startswith(')'):
                        value *= 1.3
                if re.fullmatch(r'[ \t]{2,}', lead.split('\n')[-1]):
                    value *= .6
                if (label.isupper() and 0 < rank < 5 and not question
                        and not re.search(
                            r'(?:^|\n)[ \t*#>•(-]*'
                            + chr(ord(label) - 1) + r'[.)]', before)):
                    value *= .65
                if question:
                    value *= 1.25
            elif after_stop or re.search(r'\b[Oo]ption\s*$', lead):
                value = 4.8 / decay
            elif opening:
                value = (1.0 if label.isupper() else 2.2) / decay
            else:
                value = (.4 if label.isupper() else 1.0) / decay
            if not lead.strip():
                value *= .35
        elif label in 'iIvVxX':
            value = 1.3 if line_start or opening else .05
        else:
            value = .8 if line_start else .05
    elif label.isdigit():
        if line_start:
            if token.startswith(')'):
                value = 1.3 if opening else 1.0
            else:
                value = (.7 if label == '1' else .4) if len(label) == 1 else .19
        elif opening:
            value = .4
        elif len(label) == 1 and lead.endswith(' '):
            value = .15
    elif line_start or opening:
        value = .8 if len(label) < 3 else .55
    if token.startswith(':'):
        value *= .45
    elif token[1:].strip():
        word_after_close = token.startswith(')') and token[1].isalpha()
        value *= .8 if word_after_close else .4
    elif label.isdigit() and len(token) > 1:
        value *= .4
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        before = ''
    else:
        _, before = carry
    token = prefix.token_strings[-1]
    value = marker(before, token)
    text = (before + token).replace('\\\\n', '\n').replace('\\n', '\n')
    return (doc, text[-512:]), value

programs.haiku:
"""Option-label punctuation detector (v9).

The unit fires on the punctuation that closes a list label, as in multiple-choice options:
`A.` / `B)` / `(a)` / `1)`. It is strongest when the label starts a line (or follows a bullet
such as `•`, or a question mark), and strongest still when the options follow a question
mark within the previous ~150 tokens. The first option `A`/`a` is a much stronger label than
the later ones. A label after the word "Option" gets a medium response, and a mid-line `A)`
or `(a)` a small one. Other mid-line labels and everything else are about 0.
"""

READS = ()

LETTERS = set("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz")
BULLETS = set("•◦▪●·-*")
DELIMS = {".", ")", "、", "．", "）"}


def starts_line(toks, i):
    """True if the token at i begins a line (indentation and bullets before it allowed)."""
    j = i - 1
    while j >= 0 and toks[j].strip() == "" and "\n" not in toks[j]:
        j -= 1
    if j < 0 or "\n" in toks[j]:
        return True
    if toks[j].strip() in BULLETS:
        return starts_line(toks, j)
    return False


def after_question(toks, i):
    """True if the nearest non-blank token before i ends a question."""
    j = i - 1
    while j >= 0 and toks[j].strip() == "":
        j -= 1
    return j >= 0 and toks[j].strip().endswith("?")


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    t = prefix.position
    cur = toks[t].strip()
    value = 0.0
    if t >= 2 and cur in DELIMS:
        label = toks[t - 1].strip().lstrip("(")
        is_first = label in ("A", "a")
        if len(label) == 1 and label in LETTERS:
            if starts_line(toks, t - 1) or after_question(toks, t - 1):
                value = 1.7
                if "?" in "".join(toks[max(0, t - 150) : t - 1]):
                    value += 2.0
                if is_first:
                    value += 2.5
            elif toks[t - 2].strip().lower() == "option":
                value = 2.0 if cur == ")" else 0.4
            elif is_first:
                value = 0.9 if cur == ")" else 0.4
            else:
                value = 0.2 if cur == ")" else 0.1
        elif label.isdigit() and starts_line(toks, t - 1):
            value = 1.0 if cur == ")" else 0.5
    return carry, value

programs.sol:
"""A response to twelve and to numbers ending in 2.

A 2 following an odd tens digit is strong, especially 12. An embedded 12 is weaker
than one starting a digit run; decimal/grouping separators also attenuate it.
The same rule covers fullwidth and subscript digits and Chinese numerals.
Written twelve, twelfth, odd-tens '-two', and December supply lexical signals.
A smaller parity response occurs on 6. At the first token, letters get a small
positive baseline and digits a negative one; initial ASCII 2 and 12 are suppressed
more strongly. Otherwise tokens are quiet. Boundaries reset the short history.
"""
import re
import unicodedata

READS = ()


def digit(s):
    if len(s) == 1:
        try:
            n = unicodedata.numeric(s)
            if n == int(n) and 0 <= n <= 9:
                return int(n)
        except (ValueError, TypeError):
            pass
    return None


def tens_response(n):
    if n == 1:
        return 1.40
    if n in (3, 5, 7, 9):
        return 0.84
    if n == 4:
        return 0.25
    if n == 2:
        return -0.07
    if n == 0:
        return -0.05
    if n in (6, 8):
        return 0.05
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        position, previous, before_previous = 0, '', ''
    else:
        _, position, previous, before_previous = carry
    token = prefix.token_strings[-1]
    word = previous + token
    value = 0.0
    if position == 0:
        stripped = token.lstrip()
        if digit(token) is not None:
            value = -0.18
        elif stripped[:1].isalpha():
            value = 0.25
        elif token.isspace():
            value = -0.07
        else:
            value = 0.11
    if token in ('6', '６', '₆', '六') and digit(previous) is not None:
        value = 0.12 if digit(previous) % 2 else -0.13
    if token.strip() == 'December':
        value = 0.78 if token.startswith(' ') else 0.58
    if re.search(r'\b[Tt]welve$', word):
        value = 1.65 if 'Twelve' in word else 1.40
    elif re.search(r'\b[Tt]welfth$', word):
        value = 1.20
    elif re.search(r'\b(thirty|fifty|seventy|ninety)[ -]two$', word.lower()):
        value = 1.10
    if token.strip() == '十二':
        value = 1.30
    if token in ('2', '２', '₂', '二'):
        tens = digit(previous)
        if previous == '十':
            tens = 1
        value = tens_response(tens)
        if tens == 1 and digit(before_previous) is not None:
            value -= 0.45
        if previous in ('.', ','):
            value = 0.42 * tens_response(digit(before_previous))
        if token == '2' and position == 0:
            value = -0.37
        elif token == '2' and position == 1 and previous == '1':
            value = -2.16
    return (document, position + 1, token, previous), value

"""A sparse phrase detector for lists, references, and code declarations.

Predict a large negative value at 'of' after 'list', weaker negatives for
ordinary lists and document references, and negatives at declarations such
as 'public class'. A fading count of programming words and syntax separates
programming lists from lists in prose. Python's __name__ and document starts
receive positive predictions. Unrecognized positions stay near zero; this
omits much of the component's small, token-specific background activity.
"""
READS = ()

CODE_WORDS = set('''code function method variable return import export public
private static class interface struct const def void int string array tuple
python java javascript typescript sql file directory parameter object
implementation assert isinstance'''.split())
DETERMINERS = set('''a an the this that these those my your his her its our
their whose following preceding ordered sorted full impressive disabled'''.split())
REFERENCES = {'this', 'that', 'following', 'previous', 'last', 'today', '’s'}
DOCUMENTS = {'page', 'article', 'post', 'thread', 'site', 'report'}
COLLECTIONS = set('''register corpus repertoire database catalog catalogue
library menu dictionary portfolio histogram slideshow text report'''.split())
MODIFIERS = set('''public private protected internal export abstract static
partial default final'''.split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    first = carry is None or carry[0] != doc
    if first:
        prev, code, previous_was_first = '', 0.0, False
    else:
        _, prev, code, previous_was_first = carry
    w, p = s.strip(), prev.strip()
    lower, plower = w.lower(), p.lower()
    technical = code > 1.0
    value = -0.001

    if first:
        if lower in CODE_WORDS:
            value = 0.65
        elif lower == 'the':
            value = 0.80
        elif s.startswith(' ') and w.isalpha():
            value = 0.15
        elif w.isdigit():
            value = 0.54
        elif w.isalpha():
            value = 0.46 if w.istitle() else 0.34
        else:
            value = 0.16 if s.startswith(' ') else 0.40
    elif w == ':' and p == 'Title' and previous_was_first:
        value = -4.75
    elif lower == 'const' and plower == 'export':
        value = -4.15 if previous_was_first else -1.70
    elif lower in {'class', 'interface'} and plower in MODIFIERS:
        value = -0.90
    elif w == 'name' and s == w:
        if p.endswith(').__'):
            value = 0.55
        elif p.endswith('__'):
            value = 1.60
        elif p.endswith('{"') or p.endswith("{'"):
            value = 0.30
        else:
            value = 0.10
    elif lower == 'name' and plower in {'my', 'your', 'his', 'her', 'full', 'real'}:
        value = -0.30
    elif lower == 'of' and plower in {'list', 'lists'}:
        if p[:1].isupper():
            value = -1.60 if technical else -3.60
        else:
            value = -1.15 if technical else -2.20
    elif lower == 'of' and plower in COLLECTIONS:
        value = -0.70
    elif lower == 'of' and plower in {'array', 'arrays', 'table', 'tables'}:
        value = -0.30
    elif lower in {'list', 'lists'}:
        if w[:1].isupper():
            value = 0.0 if technical else -0.35
        elif plower in DETERMINERS or p in {"'s", '’s'}:
            value = -0.10 if technical else -0.90
        elif not s.startswith(' ') or plower in {'to', 'can', 'will', 'def'}:
            value = 0.0
        else:
            value = 0.20 if technical else -0.32
    elif lower in DOCUMENTS and plower in REFERENCES:
        value = -1.10 if lower == 'post' else -0.50
    elif s.startswith(' ') and lower in {'post', 'article', 'chart', 'graph'}:
        if lower == 'chart':
            value = -0.65
        elif lower == 'graph':
            value = -0.16
        else:
            value = -0.20 if lower == 'post' else -0.02
    elif lower == 'range' and plower == 'wide':
        value = -0.80
    elif lower == 'mark' and plower in {'check', 'quotation', 'question'}:
        value = -0.55
    elif w == 'Act' and p in {'Exchange', 'Securities'}:
        value = -0.40
    elif s in {'type', 'func'} and '\n' in prev:
        value = -0.80

    evidence = (0.40 * (lower in CODE_WORDS)
                + 0.40 * any(c in s for c in '{};_`')
                + 0.25 * ('\t' in s)
                + 0.35 * ('(' in s or ')' in s))
    code = min(8.0, code * 0.97 + evidence)
    return (doc, s, code, first), value

programs.haiku:
"""Layer-1 MLP down_proj component 4268 (a list-of / document-start feature).

Mostly quiet. Main behaviours:
- the first token of each document: positive (about +0.35 on average; larger for
  capitalised words, digits and code punctuation, smaller for lowercase words that
  start with a space);
- "of" right after the word "list" (or "List"): strongly negative (about -2);
  after other collection/record nouns (table, report, database, ...): mildly negative;
- the words "list", "lists" themselves: mildly negative;
- code declarations: "public"/"export"/"pub" then "class"/"interface"/"const"/"type"
  is negative;
- "this post", "this page", "this thread": negative;
- "name": mildly positive, strongly positive in "__name__";
- the dot-leader token "··" (runs of middle dots): mildly positive, +0.44;
- ":" right after "Title" (scraped "Title: ..." lines): strongly negative.
"""
import re

READS = ()

LIST_WORDS = {"list", "lists", "List", "Lists"}
COLLECTION_WORDS = {"chart", "table", "report", "database", "dictionary", "directory",
                    "array", "catalogue", "register", "index", "menu", "portfolio", "series"}
DECL_WORDS = {"public", "export", "pub", "extern", "\texport", "<?"}
DECL_TARGETS = {"class", "interface", "const", "type", "struct", "php", "func"}
WEB_NOUNS = {"post", "page", "thread"}


def start_value(token):
    t = token.strip()
    if token.startswith("<|"):
        return 0.45
    if re.fullmatch(r"[0-9]+", t):
        return 0.55
    if re.fullmatch(r"[A-Z][a-z]+", t):
        return 0.5
    if re.fullmatch(r"[a-z]+", t) and token.startswith(" "):
        return 0.15
    return 0.35


def step(carry, prefix, upstream):
    docs = prefix.document_ids
    cur = prefix.token_strings[-1]
    if len(docs) == 1 or docs[-1] != docs[-2]:
        return None, start_value(cur)
    prev = prefix.token_strings[-2].strip()
    word = cur.strip()
    if word == "of":
        if prev in LIST_WORDS:
            return None, -2.0
        if prev.lower() in COLLECTION_WORDS:
            return None, -0.6
    if word in LIST_WORDS:
        return None, -0.3
    if prev in DECL_WORDS and word in DECL_TARGETS:
        return None, -1.0
    if prev in ("this", "This") and word in WEB_NOUNS:
        return None, -1.0
    if word == "··":
        return None, 0.44
    if prev == "Title" and word == ":":
        return None, -1.6
    if word == "name":
        return None, 1.5 if prev == "__" else 0.3
    return None, 0.0

programs.sol:
"""Approximate an enumeration-opening response.

First labels are strongest, especially after a colon. Parenthesized labels,
numbered case/step headings and discourse openers have separate rules; later
items are weaker. An initial Title: field is handled separately. Strengths are
approximate training estimates, not a model of every lexical/contextual effect.
A bounded byte buffer supplies context and resets at document boundaries.
"""
import re
import unicodedata

READS = ()
LABEL = r'(?:[0-9]{1,2}|[A-Za-z]|[ivxIVX]{2,5}|[一二三四五六七八九十]+)'
CLOSED = re.compile(r'([（(]?)(' + LABEL + r')([.)）、])(?:\s*|\$)$')
OPEN = re.compile(r'([（(]?)(' + LABEL + r')$')
MARGIN = re.compile(r'^[ \t>#*`$•-]*$')
INTRO = re.compile(r'[:：]\s*[>#*`$ \n-]*$')
SUBDIVISION = (
    r'Case|Step|Part|Stage|Phase|Option|Scenario|Example|Item|Section|Chapter|'
    r'Requirement|Hypothesis|Proposition|Recommendation|Method|Approach|Question'
)
NUMBERED = re.compile(
    r'\b(' + SUBDIVISION + r')[ \t]*([0-9]{1,2})([:.)]?)$', re.I
)
TRANSITION = re.compile(
    r'\b(First(?:ly)?|Second(?:ly)?|Third(?:ly)?|Fourth(?:ly)?|Fifth(?:ly)?|'
    r'Finally|Furthermore|Moreover|Additionally|Also|Next|Alternatively|'
    r'In addition|For example|For instance|At the same time|On (?:the )?one hand|'
    r'On the other hand|First of all|First and foremost|For one|To begin with|'
    r'In the first place|Primero|Primeiramente|Erstens|Premièrement|'
    r'Во-первых|В первую очередь|One|Two|Three)(,?)$', re.I
)
FIRST_WORDS = {
    'first', 'firstly', 'first of all', 'first and foremost', 'to begin with',
    'in the first place', 'primero', 'primeiramente', 'erstens', 'premièrement',
    'во-первых', 'в первую очередь',
}
ANNOUNCED = re.compile(
    r'\b(?:two|three|four|several|multiple|[2-9])\s+(?:\w+\s+){0,2}'
    r'(?:reasons|ways|steps|points|challenges|factors|goals|problems|conditions)',
    re.I,
)


def predict(before, text, token):
    tail = text[-180:]
    # A title field at the very beginning is another strong opening marker.
    if text == 'Title:':
        return 6.5
    m = NUMBERED.search(tail)
    if m:
        lead = tail[:m.start()]
        line = bool(MARGIN.fullmatch(lead.rsplit('\n', 1)[-1]))
        first, end = m[2] == '1', bool(m[3])
        if line:
            return (3.0 if end else 2.0) if first else (0.55 if end else 0.35)
        return (0.9 if end else 0.55) if first else 0.1
    if token == ' ' and re.search(r'\b(?:Case|Option|Hypothesis|Method)$', before):
        return 0.8
    if not token.strip():
        return 0.0

    m = CLOSED.search(tail)
    if m and (m.start() == 0 or not tail[m.start()-1].isalnum()):
        opening, label, end = m.groups()
        lead = tail[:m.start()]
        line = bool(MARGIN.fullmatch(lead.rsplit('\n', 1)[-1]))
        intro = bool(INTRO.search(lead))
        first = label in ('1', 'a', 'A', 'i', 'I', '一')
        if line or opening or end in ')）、' or intro:
            if opening or end in ')）':
                if intro:
                    return (4.5 if line else 6.0) if first else (0.8 if line else 0.0)
                prose = bool(re.search(r'[A-Za-z]{2,}[^A-Za-z]{0,8}$', lead))
                if line:
                    return 2.4 if first else 0.65
                return (0.9 if first else 0.25) if prose else (0.1 if first else 0.02)
            if not first:
                return 0.18 if line and label.isdigit() else 0.0
            if not line:
                return 1.0
            if label.isdigit():
                return 3.35 if intro else 1.35
            return 2.4 if intro else 0.75

    m = OPEN.search(tail)
    if m:
        lead = tail[:m.start()]
        line = bool(MARGIN.fullmatch(lead.rsplit('\n', 1)[-1]))
        intro = bool(INTRO.search(lead))
        continuing = before and before[-1].isalnum() and not token[0].isspace()
        if (line or intro) and not continuing:
            opening, label = m.groups()
            if label.isdigit():
                first = label == '1'
                if opening:
                    return (1.0 if intro else -0.1) if first else (0.0 if intro else 0.25)
                if intro:
                    return (1.15 if line else 0.1) if first else -0.05
                return 0.0 if first else 0.06
            if opening:
                return 0.5 if label in ('a', 'A', 'i', 'I') else 0.1

    if token.strip() in ('-', '*', '•', '–', '●', '▪', '◦'):
        lead = before + token[:len(token)-len(token.lstrip())]
        if MARGIN.fullmatch(lead.rsplit('\n', 1)[-1]):
            seen = bool(re.search(r'(?:^|\n)[ \t>*]*[-•●▪◦] ', before))
            if INTRO.search(lead):
                return 0.9 if seen else 1.25
            return 0.02 if seen else 0.14

    m = TRANSITION.search(tail)
    if m:
        phrase, comma = m[1].lower(), bool(m[2])
        lead = tail[:m.start()]
        if phrase in ('on the one hand', 'on one hand'):
            return 0.6 if comma else 5.7
        if phrase in FIRST_WORDS:
            sentence_start = not lead or re.search(r'[.!?。！？;:\n][ \t>*]*$', lead)
            if not sentence_start and not comma and phrase == 'first':
                return 1.2 if ANNOUNCED.search(lead) else 0.11
            if ANNOUNCED.search(lead):
                return 3.8 if comma else 2.6
            return 1.8 if comma else 1.0
        if phrase in ('one', 'two', 'three'):
            return 0.3 if comma else 0.0
        if phrase in ('for example', 'for instance', 'at the same time',
                      'on the other hand', 'in addition'):
            return 0.25 if comma else 0.14
        return 0.55 if comma else 0.06

    m = re.search(r'([一二三四五六七八九十])是[,、:]?$', tail)
    if m:
        return 5.8 if m[1] == '一' else 4.0
    m = re.search(r'(首先|其次|同时|此外|另外|一方面|另一方面)[,、:]?$', tail)
    if m:
        return {'首先': 1.2, '其次': 2.8, '同时': 1.0, '此外': 0.6,
                '另外': 0.7, '一方面': 2.0, '另一方面': 0.7}[m[1]]
    m = re.search(r'第([一二三四五六七八九十0-9]+)([、,。:]|章|条|点|步)?$', tail)
    if m:
        return (1.5 if m[2] in ('、', ',', ':') else 0.5) if m[1] in ('一', '1') else 0.1
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    buf = carry[1] if carry is not None and carry[0] == doc else b''
    newest = prefix.token_bytes[-1]
    before = unicodedata.normalize('NFKC', buf.decode('utf-8', 'replace'))
    text = unicodedata.normalize('NFKC', (buf+newest).decode('utf-8', 'replace'))
    token = unicodedata.normalize('NFKC', newest.decode('utf-8', 'replace'))
    before, text = before.replace('\\n', '\n'), text.replace('\\n', '\n')
    return (doc, (buf+newest)[-700:]), predict(before, text, token)

programs.haiku:
"""Enumeration markers: a list-label detector.

Plain-language summary: this component fires where the items of a list or of a
sequence are being labelled. It is strongest on
  * the ")" that closes an item label written inline in prose: "(i)", "(2)", "(a)";
  * the "." or ")" after a number at the start of a line, when a colon just before
    introduces the list ("...the following:\n1.");
  * the "1" that opens such a list, or a numbered heading ("Case 1:");
  * a line-start bullet after such a colon;
  * sequence words, "First," / "Firstly" / "Second," / "第一，", and "In addition,".
It stays near zero on citations ("Rule 23(b)(3)", "eqn (4)"), maths and code.

The program reads only the tokens so far (no lookahead). Values are rough
average activations for each case. Predictions of 1.0 or more are scaled up by
1.3: on the eval rows this lowers the output change more than it costs variance
explained (see the explanation)."""
import re

READS = ()

ROMAN = re.compile(r"[ivxIVX]{1,4}")
ORDINAL = {"First", "Firstly", "Second", "Secondly", "Third", "Thirdly", "Finally"}
ORDINAL_STEMS = {"First", "Second", "Third", "Fourth", "Fifth"}
CONNECTIVE = {"Furthermore", "Moreover", "Additionally", "Also", "In addition", "Plus", "Next", "Then"}
CHINESE_ORDER = {"第一", "第二", "第三", "一是", "二是", "三是", "首先", "其次", "同时"}
HEADINGS = {"Case", "Method", "Option", "Step", "Hypothesis", "Requirement", "Rule", "Part"}
CHINESE_NUM = set("一二三四五六七八九十")
CLOSE_PAREN = {")", ")，", "）", ".)"}
END_DOT = {".", "．"}
COMMA = {",", "，", "、"}
BULLETS = {"-", "•"}
SYMBOLS = re.compile(r"[=\$\\{}\[\]_^<>|`#]")


def label_kind(s):
    """Kind of enumeration label, ignoring a glued opening parenthesis: "1", "(i", "(A"."""
    s = s.strip().lstrip("(（")
    if s.isdigit() and len(s) <= 2:
        return "digit"
    if ROMAN.fullmatch(s):
        return "roman"
    if len(s) == 1 and s.isalpha() and s.isascii():
        return "letter"
    if s and all(c in CHINESE_NUM for c in s):
        return "chinese"
    if s in ORDINAL:
        return "ordinal"
    return None


def is_prose(toks):
    """Recent text reads as running prose: several words, no code or maths symbols."""
    text = "".join(toks[-30:])
    words = re.findall(r"[A-Za-z]{3,}", text)
    return len(words) >= 6 and not SYMBOLS.search(text)


def after_intro(toks):
    """A colon that introduces a list sits just before this line or label."""
    return bool(re.search(r":\s*\n|:\s*$", "".join(toks[-12:-1])))


def at_line_start(toks, i):
    """Token i starts a line: only a newline and indentation come before it."""
    return bool(re.search(r"\n[ \t ]*$", "".join(toks[max(0, i - 3):i])))


def opens_item(tok, before_tok=""):
    """True if the token opens a list item's label: a spaced "(", or a "(" at a line
    start. A "(" glued to a word is usually a citation or a function call."""
    if tok == "(":
        return "\n" in before_tok
    return tok.endswith("(") and tok.startswith(" ")


def marker_value(toks):
    """The raw activation estimate for the newest token."""
    cur = toks[-1]
    prev = toks[-2]
    # sequence words, and the comma after them
    if cur in ("Firstly", " Firstly"):
        return 2.5
    if cur == "ly" and prev in ORDINAL_STEMS:
        return 2.5
    if cur in ("First", " First"):
        return 0.8
    if cur in COMMA and prev.strip() in CONNECTIVE | CHINESE_ORDER:
        return 2.0 if prev.strip() in ORDINAL | CHINESE_ORDER else 0.6
    # a "1" (or bullet) that starts a list under an introducing colon, or a numbered heading
    if cur.strip() in BULLETS | {"1"}:
        if "\n" in prev and after_intro(toks):
            return 1.2 if cur.strip() in BULLETS else 1.3
        if cur.strip() == "1" and toks[-3].strip() in HEADINGS:
            return 2.0
    kind = label_kind(prev)
    if kind is None:
        return 0.0
    line_start = at_line_start(toks, len(toks) - 2)
    before = toks[-3]
    before2 = toks[-4] if len(toks) >= 4 else ""
    # a label glued to its "(" at a line start ("\n(i"), not a function call such as "q(x"
    glued = prev.startswith(("(", "（")) and (len(toks) < 4 or toks[-3][-1:].isspace())
    if cur in CLOSE_PAREN and (glued or opens_item(before, before2)):
        value = {"roman": 3.0, "chinese": 1.9, "digit": 1.7, "letter": 1.3}.get(kind, 0.0)
        return value if is_prose(toks) else 0.5 * value
    if cur in CLOSE_PAREN and line_start and kind == "digit":
        return 1.5 if after_intro(toks) or is_prose(toks) else 0.5
    if cur in END_DOT and line_start and kind == "digit":
        return 2.7 if after_intro(toks) else 0.4
    if cur in COMMA and kind == "ordinal":
        return 2.0
    return 0.0


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    if len(toks) < 3:
        return carry, 0.0
    value = marker_value(toks)
    if value >= 1.0:
        value *= 1.3
    return carry, value

programs.sol:
"""Animal vocabulary and labial--L spelling clusters.

Animal vocabulary is positive: English/French stems, Chinese 动物/動物,
and inflections after the Russian stem живот. Short animal-word completions
are stronger than whole words. Plant words have a weaker positive value.

The negative signal is strongest for Cyrillic L after labial consonants
(V/M/B/P), especially soft L and short suffixes. Latin versions are weaker.
TOML and MathML completions are also negative. Two format rules handle
a document-opening 'Title:' and runs of middle dots. Other inputs are zero.
"""
import regex

READS = ()
LATIN = regex.compile(r'^\p{Latin}+$')
CYRILLIC = regex.compile(r'^\p{Cyrillic}+$')
LETTERS = regex.compile(r'\p{L}+$')


def cluster_value(token, previous):
    """Strength of an L-bearing fragment, not of a whole word."""
    t, p = token.lower(), previous.lower()
    n = len(t)
    if CYRILLIC.fullmatch(t):
        if t.startswith('л') and p:
            strength = {'в': 8.0, 'м': 7.5, 'б': 5.0,
                        'п': 3.5, 'ф': 0.7, 'т': 2.5}.get(p[-1], 0.0)
            shortness = (1.0 if n == 1 else 0.85 if n == 2 else
                         0.65 if n == 3 else 0.4 if n == 4 else 0.25)
            if n > 1 and t[1] in 'аоуы':
                shortness *= 0.15
            return -strength * shortness
        if t.startswith(('вл', 'мл', 'бл', 'пл')):
            strength = {'в': 4.4, 'м': 3.0, 'б': 1.4, 'п': 1.5}[t[0]]
            return -strength * (1.0 if n == 2 else 0.15)
    if LATIN.fullmatch(t) and LATIN.fullmatch(p.strip()):
        # Capital L after lowercase m commonly denotes millilitres.
        if not token[0].islower():
            return 0.0
        if t.startswith('l') and len(p.strip()) > 1:
            strength = {'m': 2.5, 'v': 3.0, 'b': 1.1,
                        'p': 0.7, 'f': 0.2}.get(p[-1], 0.0)
            if t == 'ly' and p.endswith('m'):
                strength = 0.6
            if t.startswith('ley'):
                strength *= 1.6
                if p.endswith('ve'):
                    strength = 4.0
            return -strength * (1.0 if n <= 3 else 0.2)
        if t.startswith(('ml', 'vl', 'bl', 'pl')) and n <= 4:
            return -{'m': 0.6, 'v': 2.2, 'b': 0.3, 'p': 0.2}[t[0]]
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, stem, old_cluster, position = '', '', 0.0, 0
    if carry is not None and carry[0] == doc:
        previous, stem, old_cluster, position = carry[1:]
    token = prefix.token_strings[-1]
    t = token.lower()
    continues = bool(t) and bool(stem) and t[0].isalpha()
    if (token[:1].isupper() and not token.isupper() and
            previous[-1:].islower()):
        continues = False  # CamelCase, but not an acronym like MathML.
    # Whitespace or punctuation starts a fresh word.
    m = LETTERS.search((stem if continues else '') + t)
    word = m[0][-32:] if m else ''

    negative = cluster_value(token, previous) if continues else 0.0
    value = negative
    if value == 0 and continues and old_cluster < -2:
        if CYRILLIC.fullmatch(token):
            value = 0.25 * old_cluster

    bare = t.strip()
    if bare in ('animal', 'animals'):
        value = 4.8 if bare == 'animal' else 3.5
        if token.strip()[0].isupper():
            value = 5.3
    elif bare in ('动物', '動物'):
        value = 4.0
    elif previous.strip().lower() == 'живот' and t.startswith('н'):
        value = 8.3
    elif word.startswith('animal') and continues:
        value = 7.0 if len(stem) < 6 else 5.0
    elif continues and word in ('anima', 'animaux'):
        value = 4.5 if word == 'anima' else 5.6
    elif (continues and stem.startswith('anim') and
          t[:1] in 'aiu' and len(t) <= 4):
        value = 3.3
    elif bare == 'anim':
        value = 1.8
    elif stem.endswith('mamm') and continues and t.startswith('al'):
        value = 7.7 if t == 'al' else 4.4
    elif bare in ('mammal', 'mammals'):
        value = 1.3
    elif bare in ('plant', 'plants'):
        value = 0.7
    elif previous.strip().lower() == 'động' and bare == 'vật':
        value = 7.0

    # Two markup/configuration names end in the unusual M--L cluster.
    if continues and word == 'toml':
        value = -6.6
    elif continues and word == 'mathml':
        value = -4.8
    if token == ':' and previous == 'Title' and position == 1:
        value = 8.7
    if len(token) >= 2 and not token.strip('·'):
        value = -1.03
    return (doc, token, word, negative, position + 1), float(value)

