DEMONSTRATIVES = {'この', 'その', 'あの', 'どの'}
VERB_ENDINGS = {
    'した', 'する', 'された', 'している', 'しています', 'ます', 'します', 'し',
}


def response(text):
    # Baseline, repetition gain, and which earlier marker to look for.
    if text == '的':
        return -1.76, 6.6, '的'
    if '的' in text:
        return (-0.52 if text.startswith('的') else -0.45), 2.8, '的'
    if text == '之':
        return -0.96, 3.5, '的'
    if '之' in text:
        return -0.09, 0.0, None
    if text in DEMONSTRATIVES:
        return -0.06, 0.0, None
    if text.endswith(('こと', 'もの')):
        return -0.98, 0.45, 'の'
    if text == 'の':
        return -1.17, 3.1, 'の'
    if 'の' in text:
        baseline = -0.46 if text.startswith('の') else -0.21
        if not text.startswith('の') and not text.endswith('の'):
