    return 0.0, 0.0, None


def repetition(recent, marker):
    for lag, previous in enumerate(reversed(recent), 1):
        if marker not in previous:
            continue
        if marker == 'の' and previous in DEMONSTRATIVES | {'もの'}:
            continue
        # Text merged after an earlier marker separates the two occurrences too.
        trailing = len(previous) - previous.rfind(marker) - 1
        distance = lag + trailing
        # Decay becomes steeper beyond three steps.
        weight = 0.7 ** (distance - 1) * 0.74 ** max(0, distance - 3)
        if marker == 'の' and not previous.endswith(marker):
            weight *= 0.55
        return weight
    return 0.0


