"""layers.1.mlp.down_proj:4276 - a "sad / sick / sink" spelling detector.

This component goes strongly negative on the last piece of a word that is spelled
s-a-d, s-i-c-k or s-i-n-k (sad, sick, sickness, sink, heatsink, homesick, Russian
сад/фасад/посад) and on the Chinese character 幸 (xìng, "fortunate"). It is weakly
negative on other "s-a/s-i" words (saw, sax, sash, sank, suck, Sasha, Sachs) and weakly
positive on saint, sake, sache, sant, sao. It is silent on almost every other token.

The program reads the word the current token finishes (the letters since the last space,
lower-cased, within one document) and looks it up in these families.
"""

import re

READS = ()

# Words ending in the spelling sad / sick / sink (or Russian сад "garden", as in фасад).
FAMILY = re.compile(r"(sad|sick|sink|sinks|сад)$")
FAMILY_VALUE = -4.0

# Individual words: strong ones are the sad/sick family, weak ones the other s-a/s-i words.
WORDS = {
    "sickness": -5.9, "sadness": -2.5, "sadly": -1.4, "saddle": -2.5, "sinking": -2.7,
    "sank": -2.1, "sunk": -1.3, "suck": -1.5, "sax": -2.1, "sach": -2.3, "sash": -4.7,
    "sass": -2.6, "sasha": -2.7, "sachs": -5.0, "saw": -0.8,
    "saint": 0.7, "sake": 1.3, "sache": 2.2, "sant": 1.0, "sao": 2.1,
}

# Single characters that are strongly negative on their own.
CHARACTERS = {"幸": -8.8, "辛": -2.6}


def _word_so_far(prefix):
    """Letters of the word the current token ends, lower-cased, from the document's start."""
    here = prefix.document_ids[prefix.position]
    pieces = []
    for i in range(prefix.position, -1, -1):
        if prefix.document_ids[i] != here:
            break
        text = prefix.token_strings[i]
        if any(c.isspace() for c in text):
            pieces.append(text[max(j for j, c in enumerate(text) if c.isspace()) + 1:])
            break
        pieces.append(text)
    word = "".join(reversed(pieces)).lower()
    return re.sub(r"[^a-zа-я一-鿿]", "", word)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip()
    if token in CHARACTERS:
        return carry, float(CHARACTERS[token])
    word = _word_so_far(prefix)
    if word in WORDS:
        return carry, float(WORDS[word])
    if FAMILY.search(word):
        return carry, float(FAMILY_VALUE)
    return carry, 0.0

