'Title:' header has a separate negative response.
"""
import math
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
LANGUAGES = (
    'en', 'nl', 'fi', 'hu', 'ro', 'de', 'fr', 'es', 'it', 'pt',
    'pl', 'cs', 'tr', 'sv', 'da', 'nb', 'af', 'ru', 'uk',
)


@lru_cache(maxsize=60000)
def frequencies(word):
    values = [max(0.0, zipf_frequency(word, lang) - 2.0)
              for lang in LANGUAGES]
    best = max(values)
    return tuple(v - best for v in values), best


def spelling_responses(token, previous):
    """Responses by language to recognizable endings and short syllables."""
    s = token.lower().strip()
    p = previous.lower().strip()
    attached = not token[:1].isspace()
    hu = nl = fi = ro = 0.0
