            nl = -2.2
        elif s == 'as':
            nl = -3.4
        elif attached and s in ('us', 'ies'):
            nl = -3.0
        elif attached and s == 'ie':
            nl = -1.4
        elif 's' in s and len(s) <= 4:
            nl = -1.1

