    logits = [a + 0.4 * b for a, b in zip(scores, current)]
    best = max(logits)
    weights = [math.exp(1.3 * (x - best)) for x in logits]
    total = sum(weights)
    probs = dict(zip(LANGUAGES, (x / total for x in weights)))
