    elif lower == 'to' and previous.lower() == 'refers':
        value = -0.95
    return (doc, word, tail[-2:]), value

programs.haiku:
"""Finger / point-at / refer-to detector (negative direction).

The component writes a large negative value into the residual stream on words that
mean "finger" or "point at / indicate / refer to". It is almost silent everywhere else.

- The Chinese character 指 (zhǐ: finger, or "point at") is the strongest trigger:
  about -7 when it stands alone as a token.
- Compounds built on 指 (指导, 是指, 手指, 指数, 指定, ...) fire more weakly, about -2.5.
- English "finger" / "fingers" (and "Finger", "ingers" after "F") fire about -3.3.
- Vietnamese "chỉ" (point / only) fires about -4.3.
- Korean 지, the Sino-Korean reading of 指, fires about -2.5; 지도 (指導, guidance) about -4.5.
- "refers to" / "refer to": a weak -1 on "to".

Everything else is 0. The program looks only at the current token and the one before it
(in the same document), so it has no carry.
"""

READS = ()

ZHI = "指"
FINGER_WORDS = {"finger", "fingers", "ingers"}
VIETNAMESE_CHI = {"chỉ"}
KOREAN_JI = {"지"}
KOREAN_GUIDE = {"지도"}  # 指導, guidance
REFER_WORDS = {"refers", "refer", "referred", "referring"}


def activation(token, previous):
    word = token.strip().lower()
    if token == ZHI:
        return -7.0
    if ZHI in token:
        return -2.5
    if word in FINGER_WORDS:
        return -3.3
    if word in VIETNAMESE_CHI:
        return -4.3
    if word in KOREAN_JI:
        return -2.5
    if word in KOREAN_GUIDE:
        return -4.5
    if word == "to" and previous.strip().lower() in REFER_WORDS:
        return -1.0
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    same_doc = len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    previous = prefix.token_strings[-2] if same_doc else ""
    return None, float(activation(token, previous))

programs.sol:
"""Approximate a mixed lexical, formatting, and document-start signal.

'Instance' is negative, especially just after a table-like separator;
web-related nouns are also negative. Small offsets summarize token shape,
Han script and closing markup. Repeated middle-dot separators get a larger
negative value. At document starts, letters and digits behave differently,
so the first token has separate rules, followed by a fading negative offset.
These summarize training patterns, not a general semantic classifier.
"""
import math
import unicodedata
import regex

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    text = token.strip()
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, previous = 0, ''
    else:
        position, previous = carry[1], carry[2]
    alpha = text.isalpha()
    digit = text.isdigit()
    punct = bool(text) and all(
        unicodedata.category(c).startswith('P') for c in text
    )
    symbol = bool(text) and all(
        unicodedata.category(c).startswith('S') for c in text
    )
    han = bool(regex.search(r'\p{Script=Han}', text))
    partial = '\ufffd' in text

    value = -0.012
    value += -0.006 * token.startswith(' ')
    value += -0.015 * alpha + 0.008 * digit
    value += 0.012 * punct + 0.025 * symbol
    value += 0.012 * text.istitle() - 0.030 * partial
    value += -0.042 * han
    if not text:
        value = -0.003
    if '_' in token:
        value -= 0.006
    if '\\' in token:
        value -= 0.010
    if text.startswith('</'):
        value -= 0.12
    if text.startswith(('/*', '//')):
        value -= 0.04
    if text.lower() in ('web', 'website', 'internet'):
        value = -0.15
    if text.lower() in ('instance', 'instances'):
        value = -0.19
        if previous.endswith('->'):
            value = -0.37
        elif previous.endswith(('|', ':', ',', '—')):
            value = -0.49
    if text and set(text) == {'·'}:
        value = -0.79 if previous and set(previous) == {'·'} else -0.08

    if position == 0:
        if partial:
            value = -0.09
        elif digit:
            value = -0.27
        elif regex.search(r'\p{Script=Cyrillic}', text):
            value = 0.74
        elif alpha:
            value = 0.43
        elif not text:
            value = 0.14
        elif punct:
            value = 0.19
        elif symbol:
            value = 0.05
        else:
            value = 0.20
    else:
        value += -0.055 * math.exp(-position / 16)
        value += 0.006 * math.exp(-position / 64)
    return (doc, position + 1, text), float(value)

"""Detect unusual whitespace: trailing spaces or tabs joined to a newline.

An ordinary line break has little response; a line break carrying horizontal
whitespace has a large positive one. Non-breaking spaces and long runs of
newlines give smaller responses. A separate space after one space, or a tab
after a space or tab, also responds strongly. State resets per document.
Most other tokens have near-zero response.
"""
READS = ()


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    prev = carry[1] if carry and carry[0] == prefix.document_ids[-1] else ""
    value = 0.0
    if s.isspace():
        lines = s.count('\n')
        spaces = s.count(' ')
        tabs = s.count('\t')
        if lines and (spaces or tabs):
            if tabs:
                value = 1.86 if s == '\t\n' else 0.95
            elif spaces == 1:
                value = 2.75 if lines == 1 else 1.72
            elif spaces == 2:
                value = 1.65
            elif spaces <= 4:
                value = 1.25
            else:
                value = 0.90
        elif s == ' ' and prev == ' ':
            value = 2.43
        elif s == '\t' and prev == '\t':
            value = 1.28
        elif s == '\t' and prev == ' ':
            value = 2.10
        elif '\xa0' in s:
            value = 0.38
        elif lines >= 3:
            value = 0.45
        elif s == '\r':
            value = 0.55
    elif s.endswith('\n\n\n'):
        value = 0.70
    return (prefix.document_ids[-1], s), value

