    joined = tail + raw
    added = joined.decode('utf-8', 'ignore')[
        len(tail.decode('utf-8', 'ignore')):]
    text = added.strip()
    previous = before[-1:]
    only_dots = only_dots and bool(added) and set(added) <= {'·'}
    value = -0.001
    if first:
        if not text:
            value = -0.14
        elif text in {'import', 'from', 'require', 'include'}:
            value = -0.8
        elif text.startswith('#'):
            value = -0.5
        elif text.startswith('\\'):
            value = 0.7
        elif not text.isascii():
            script = unicodedata.name(text[0], '').split(' ')[0]
            if script in {'CYRILLIC', 'GREEK', 'HIRAGANA',
                          'KATAKANA', 'THAI', 'HANGUL'}:
                value = 0.7 if len(text) == 1 else 0.25
            elif script == 'CJK':
                value = 0.2
        elif text.isalpha() and text.istitle():
            value = 0.13
    if text == '··':
        value = 1.15 if only_dots else 0.0
    # Korean syllables; 등록 and 기록 are registration and recording.
    elif text in {'영', '록'}:
        value = -2.4 if raw.startswith(b' ') else -3.0
        if text == '록':
            value = -2.5 if previous in {'등', '기'} else -7.0
        elif text == '영' and previous == '경':
            value = -1.5
    elif text == '引用':
        value = -3.0
    elif text == '维护':
        value = -0.6
    elif text in {'담', '용'}:
        value = -1.0
        if text == '담':
            value = -4.0 if len(raw) == 1 else -0.35
    # Camp/business characters, especially strong in Japanese form 営.
    elif any(ch in text for ch in '营營営'):
        value = -5.5 if len(text) == 1 else -0.5
        if text == '営':
            value = -7.2
        elif len(text) == 1 and previous in {'经', '經', '运', '運', '本', '士'}:
            value = -1.8
    # Recording characters, attenuated in familiar compound words.
    elif text in {'录', '錄', '録'}:
        value = -6.5
        if previous in {'记', '記', '纪', '紀'}:
            value = -3.0 if text == '録' else -0.9
        elif previous == '登':
            value = -2.5 if text == '録' else -0.6
        elif previous == '目':
            value = -3.0
        elif previous in {'讯', '訊'}:
            value = -0.9
        elif previous == '刻':
            value = -4.0
    elif '录' in text or '錄' in text or '録' in text:
        value = -0.3
        # Hiring/admission/collection versus recording audio or video.
        if text in {'录用', '录取', '收录'}:
            value = -5.2
        elif text in {'录制', '录像', '录音', '目录'}:
            value = -2.7
        elif text == '记录':
            value = -0.9
        elif text == '登录':
            value = 0.0
    elif any(ch in text for ch in '饮飲'):
        value = -1.0
        if len(text) == 1:
            value = -4.2 if text == '饮' else -2.8
    elif '抄' in text:
        value = -2.0 if len(text) == 1 else 0.0
    elif '灌' in text:
        value = -2.0 / len(text)
    elif '煎' in text:
        value = -1.9 / len(text)
    return (doc, joined[-3:], (before + added)[-1:], only_dots), value

"""An 'in' spelling detector, with weaker responses to containment words.

Short in/yn pieces are strongest inside words. A high-vowel letter followed
by n can straddle two tokens; a short continuation after in also responds.
Diphthong-like spellings and -ing are weaker. Transliteration handles related
alphabetic spellings, not ideographs. This is a local spelling approximation,
not a pronunciation dictionary or a reconstruction of all contextual spikes.
"""
import re
import unicodedata
from functools import lru_cache
from anyascii import anyascii

READS = ()

# Prepositions expressing 'in', and related containment words.
CONTAINMENT = {
    'en': 0.72, 'em': 0.25, 'im': 0.22, 'dans': 0.40,
    'в': 0.43, 'في': 0.30, '在': 0.22, '内': 0.22,
    'inside': 0.20, 'within': 0.20, 'into': 0.20,
}


@lru_cache(None)
def latin(text):
    return anyascii(text).lower()


@lru_cache(None)
def alphabetic(text):
    return bool(text) and all(
        ch.isalpha() and any(script in unicodedata.name(ch, '')
                            for script in ('LATIN', 'CYRILLIC', 'GREEK', 'ARABIC'))
        for ch in text)


@lru_cache(None)
def high_vowel(ch):
    plain = ''.join(c for c in unicodedata.normalize('NFD', ch.lower())
                    if not unicodedata.combining(c))
    return bool(plain) and plain in set('iyиыιي')


def predict(text, previous):
    raw = text.strip().lower()
    s, prev = latin(text).strip(), latin(previous)
    inside = alphabetic(text[:1]) and alphabetic(previous[-1:])
    if not inside and raw in CONTAINMENT:
        return CONTAINMENT[raw]
    if not inside and s == 'in' and alphabetic(raw):
        return 1.03
    if not alphabetic(raw) or not s.isalpha():
        return 0.002

    # For example, Cyrillic и + на, or Latin i + n.
    if inside and high_vowel(previous[-1:]) and s.startswith('n'):
        if s.startswith('ng') or len(s) > 4:
            return 0.002
        if len(prev) > 1 and prev[-2] in 'aeou':
            return 0.75
        if len(s) == 1:
            return 2.8
        return 2.5 if s[1] in 'aeiouy' else 0.75

    # Continuations of an in/yn piece, strongest for a single vowel.
    if inside and re.search('[iy]n$', prev):
        if len(s) > 3:
            return 0.002
        if s[0] in 'aeiouy':
            return (0.0, 2.55, 1.2, 0.4)[len(s)]
        return 0.6

    match = re.search('[iy]n(?!g)', s)
    if match and len(s) <= 9:
        before, after = s[:match.start()], s[match.end():]
        if not before and inside and prev.endswith('e'):
            return 0.10
        if not before and inside and prev[-1:] in 'aou' and not prev.endswith('qu'):
            return 0.20
        if before and before[-1] in 'aeou':
            return 0.11
        if inside:
            if len(after) > 1:
                return 0.48
            if not before:
                return 1.52 if not after else 1.58 if after in 'aeiouy' else 0.97
            return 0.84 if not after else 0.45 if after in 'aeiouy' else 0.25
        if len(s) <= 5:
            return 0.47 if not after else 0.18
        return 0.12
    return 0.002


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    text = prefix.token_strings[-1]
    return (doc, text), predict(text, previous)

"""Detect unusual spellings of 'of', rather than the ordinary preposition.

Negative responses mark Of-ending code names, f continuing an o-ending
fragment, spaced-out 'o f', and elided 'o\'' spellings.  An 'of' token
following o has the opposite sign.  Extra rules cover initial Greek oi,
Cyrillic of, and Japanese o-vowel/fu sequences.  NUL-separated text is read
without its separators.  Other text is quiet, with a small negative default
at document starts.
"""
import re
import unicodedata

READS = ()
# Katakana syllables ending in the vowel o.
O_KANA = 'オォコゴソゾトドノホボポモヨョロヲ'


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous = '' if first else carry[1]
    tail = b'' if first else carry[2]
    before = tail.decode('utf-8', 'ignore').replace('\x00', '')
    token = prefix.token_strings[-1]
    low = token.lower()
    bare = token.strip()
    word = low.lstrip(' ._*<(')
    last = before[-1:]
    folded = ''.join(c for c in unicodedata.normalize('NFD', last)
                     if not unicodedata.combining(c)).lower()
    after_o = folded == 'o'
    value = -0.22 if first else 0.0

    if token == ' of':
        value = -0.62 if first else -0.03
    elif token == ' Of':
        value = 0.15
    elif low == 'of':
        value = 2.8 if after_o else -0.15
    elif word == 'nof' and before.endswith('\\'):
        # The n belongs to an escaped newline, leaving an unspaced 'of'.
        value = -6.0
    elif word in ('typeof', 'keyof'):
        value = -4.0
    elif word == 'instanceof':
        value = -4.3 if 'InstanceOf' in token else -2.9
    elif low == '-of':
        value = -0.25
    elif word.endswith('of') and len(word) > 2:
        # Long oo and the productive pro-/auto- stems are different patterns.
        if word.endswith(('oof', 'prof', 'autof')) or word == 'thereof':
            value = 0.0
        elif word == 'eof':
            value = -0.3 if previous.strip() in ("'", '"') else -1.5
        elif word == 'sizeof':
            value = -1.0 if token.startswith(' ') else -2.0
        elif word.endswith('indexof'):
            value = -0.3 if word.startswith('last') else -2.4
        elif word.endswith('valueof'):
            value = -1.0
        else:
            value = -1.6
    elif low in ('.of', '_of'):
        value = -0.5
    elif word.startswith('of') and len(word) == 3 and word[-1] != 'f':
        value = -0.7
    elif 'tofixed' in low:
        value = -1.0
    elif previous.strip() == 'o' and token == ' f':
        value = -4.5
    elif previous.strip() in ('o', 'O') and bare in ("'", '’', 'ʼ'):
        if previous.strip() == 'o':
            value = -4.7 if bare == "'" else -2.2
        else:
            value = -1.3
    elif after_o and token[:1].lower() == 'f':
        if token in ('f', 'F'):
            if b'\x00' in tail[-4:]:  # NUL-separated, UTF-16-like text.
                value = -7.0
            elif previous.endswith('fo'):
                value = -5.0
            else:
                value = -3.0 if token == 'F' else -2.0
        elif re.fullmatch(r'f[aeo]?|f[ae](n|r)|ff', low):
            value = -1.3
        elif low == 'ft':
            value = -0.4
    elif len(previous) == 1 and previous in O_KANA and token.startswith('フ'):
        value = -2.2
    elif folded == 'ο' and token.startswith('ι'):
        # Initial Greek oi, not an oi sequence inside a longer word.
        value = 0.0 if before[-2:-1].isalpha() else -1.4
    elif last.lower() == 'о' and token.startswith('ф'):
        value = 0.0 if before.lower().endswith('про') else -1.8

    tail = (tail + prefix.token_bytes[-1])[-64:]
    return (doc, token, tail), float(value)

