"""A small document-start response, not a general semantic detector.

Opening source declarations get a negative estimate. Other first tokens
are grouped by script, capitalization, digits and whitespace. Later tokens
have only a small negative offset that fades with distance from the start.
These are coarse averages: most token-specific variation is not explained.
"""

import math

READS = ()

# Common ways a source file begins a declaration or import.
SOURCE_OPENERS = frozenset({
    "package", "using", "import", "from", "class", "namespace",
    "#include", "#pragma",
})


def step(carry, prefix, upstream):
    new_document = (
        carry is None
        or prefix.document_ids[-1] != prefix.document_ids[-2]
    )
    position = 0 if new_document else carry + 1
    if position:
        return position, 0.003 - 0.016 * math.exp(-position / 65.0)

    token = prefix.token_strings[-1]
    word = token.strip()
    if token == "<|im_start|>":
        value = -0.313
    elif token in SOURCE_OPENERS:
        value = -1.14
    elif token.isspace():
        if "\n" in token:
            value = 0.30
        else:
            value = -0.20 if len(token) > 1 else 0.10
    elif not token.isascii():
        value = 0.15
    elif word.isdigit():
        value = 0.145
    elif word[:1].isupper():
        value = -0.10
    else:
        value = 0.05
    return position, value

programs.haiku:
"""layers.1.mlp.down_proj:4287 — a document-start feature.

Almost all of this component's activation is small noise around zero. Its one readable
pattern is at the first token of each document in a packed row (position 0 of a row, or
the first token after a document break). There the model has no earlier context, so the
value depends only on what kind of token starts the document:

- a code keyword that opens a source file (package, import, #include, using, class, ...)
  is strongly negative;
- a chat/markup token (<|im_start|>, <|endoftext|>, ...) is negative;
- a capitalised word is mildly negative;
- a digit, a line break, or a non-ASCII character is positive;
- a function word (" of", " a", " is", ...) is mildly positive.

Everywhere else the program predicts 0. Values are the class means measured on training rows.
"""

READS = ()

CODE_START = {
    "package", "#include", "using", "namespace", "use", "import", "class", "const",
    "from", "function", "def", "<?", "<?php", "return", "#!/", "/*", "//",
}
FUNCTION_WORDS = {
    " the", " of", " a", " an", " to", " in", " and", " is", " that", " for", " with",
    " on", " as", " by", " at", " from", " or", " it", " this", " are", " was", " be",
}
MEAN = {
    "code": -0.69, "special": -0.29, "capital": -0.13, "other": 0.04,
    "space_word": 0.05, "function_word": 0.08, "digit": 0.13, "newline": 0.19,
    "non_ascii": 0.15,
}


def kind(s):
    if s.startswith("<|"):
        return "special"
    if s.strip() in CODE_START:
        return "code"
    if "\n" in s:
        return "newline"
    if s in FUNCTION_WORDS:
        return "function_word"
    if s[:1] == " ":
        return "space_word"
    if s[:1].isdigit():
        return "digit"
    if s[:1].isupper():
        return "capital"
    if any(ord(c) > 127 for c in s):
        return "non_ascii"
    return "other"


def step(carry, prefix, upstream):
    t = prefix.position
    starts_document = t == 0 or prefix.document_ids[t] != prefix.document_ids[t - 1]
    if not starts_document:
        return carry, 0.0
    return carry, MEAN[kind(prefix.token_strings[t])]
